Object.assign(window.IND_FEED_BODY, {"io-marathas-sikhs-1":{"route":"#/era/marathas-sikhs|objects:1","cta":"See it in Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:objects:1","title":"Found from Forts, Horses and the Gurus","body":"The Golden Temple at Amritsar","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"io-marathas-sikhs-2":{"route":"#/era/marathas-sikhs|objects:2","cta":"See it in Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:objects:2","title":"Found from Forts, Horses and the Gurus","body":"An Ahom coin","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-m0":{"route":"#/era/marathas-sikhs|moments:0","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:moments:0:what","title":"from 1469","body":"Guru Nanak begins the line of ten Gurus — teaching one humanity, honest work, and a kitchen where everyone eats together.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-m1":{"route":"#/era/marathas-sikhs|moments:1","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:moments:1:what","title":"1671","body":"On the Brahmaputra at Saraighat, the Ahom general Lachit Borphukan turns back a Mughal fleet.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-m2":{"route":"#/era/marathas-sikhs|moments:2","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:moments:2:what","title":"1674","body":"Shivaji is crowned Chhatrapati at Raigad fort.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-m3":{"route":"#/era/marathas-sikhs|moments:3","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:moments:3:what","title":"1699","body":"Guru Gobind Singh founds the Khalsa at Anandpur.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-m4":{"route":"#/era/marathas-sikhs|moments:4","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:moments:4:what","title":"the 1700s","body":"Maratha power spreads until much of India answers to Pune — while in Assam the Ahoms complete six centuries of unbroken rule.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-m5":{"route":"#/era/marathas-sikhs|moments:5","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:moments:5:what","title":"1801–1839","body":"Ranjit Singh rules his Sikh kingdom from Lahore, wearing the Koh-i-noor on his arm.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-t0":{"route":"#/era/marathas-sikhs|today:0","cta":"Sail to Forts, Horses and the Gurus","art":null,"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:today:0:what","title":"Still there today · Raigad district","body":"Raigad, the fort where Shivaji was crowned","facts":[["Where","Raigad district"],["In","Maharashtra"],["From","Forts, Horses and the Gurus"]]},"it-marathas-sikhs-t1":{"route":"#/era/marathas-sikhs|today:1","cta":"Sail to Forts, Horses and the Gurus","art":null,"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:today:1:what","title":"Still there today · Amritsar","body":"Harmandir Sahib, the Golden Temple — the kitchen still feeds everyone","facts":[["Where","Amritsar"],["In","Punjab"],["From","Forts, Horses and the Gurus"]]},"it-marathas-sikhs-t2":{"route":"#/era/marathas-sikhs|today:2","cta":"Sail to Forts, Horses and the Gurus","art":null,"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:today:2:what","title":"Still there today · Sivasagar","body":"The Rang Ghar and the Ahom monuments","facts":[["Where","Sivasagar"],["In","Assam"],["From","Forts, Horses and the Gurus"]]},"it-marathas-sikhs-f0":{"route":"#/era/marathas-sikhs|figures:0","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:figures:0:line","title":"Shivaji","body":"Took forts the hard way — up the cliff nobody watched — and built a state from mountains the empires could not hold.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-f1":{"route":"#/era/marathas-sikhs|figures:1","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:figures:1:line","title":"Guru Nanak","body":"Asked why anyone should be a stranger, and answered with a kitchen where everyone sits on the floor together.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-f2":{"route":"#/era/marathas-sikhs|figures:2","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:figures:2:line","title":"Jijabai","body":"Shivaji's mother, who raised him on stories of heroes — a story in this app remembers her telling them.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"it-marathas-sikhs-f3":{"route":"#/era/marathas-sikhs|figures:3","cta":"Sail to Forts, Horses and the Gurus","art":null,"sources":["Maratha-period records and fort archaeology","Sikh historical tradition and the Gurus' compositions","Ahom Buranji chronicles","Contemporary European and Persian accounts of Ranjit Singh's court"],"why":"Forts, Horses and the Gurus, about 1600–1850","src":"era:marathas-sikhs:figures:3:line","title":"Lachit Borphukan","body":"The Ahom general who beat a Mughal fleet on the river at Saraighat — Assam still celebrates him every year.","facts":[["When","about 1600–1850"],["Where","Maharashtra"]]},"ss-fk.boita-bandana-1":{"src":"story:fk.boita-bandana:scenes:1:text","title":"Little Boats for the Big Sailors · 2 of 9","body":"The boats are made of banana stem and bark and coloured paper, and each one is loaded like a real ship in miniature: a lamp, betel leaves, flowers, a coin. At first light, each family sets its little boat on the water, lamp burning — and suddenly the whole dark river is a fleet of drifting stars.","art":"art/story/sm/fk-boita-bandana.jpg","route":"#/story/fk.boita-bandana|s1","cta":"Read from here","why":"A moment from Little Boats for the Big Sailors","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.boita-bandana-2":{"src":"story:fk.boita-bandana:scenes:2:text","title":"Little Boats for the Big Sailors · 3 of 9","body":"As the boats go out, everyone says the old cry together — \"Aa ka ma boi!\" — a counting-call so ancient that it names the sailing months themselves; ask an Odia family to say it for you properly. The custom is called Boita Bandana: the honouring of the boats. But which boats?","art":"art/story/sm/fk-boita-bandana.jpg","route":"#/story/fk.boita-bandana|s2","cta":"Read from here","why":"A moment from Little Boats for the Big Sailors","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.boita-bandana-3":{"src":"story:fk.boita-bandana:scenes:3:text","title":"Little Boats for the Big Sailors · 4 of 9","body":"The huge ones. Many centuries ago, Odisha — Kalinga, in those days — was one of the great seafaring lands of India. Its merchants, the sadhabas, built tall ships called boitas, and when the winds turned after the rains, whole fleets set out across the Bay of Bengal — to Sri Lanka, to Burma, and all the way to the islands of Bali, Java and Sumatra.","art":"art/story/sm/fk-boita-bandana.jpg","route":"#/story/fk.boita-bandana|s3","cta":"Read from here","why":"A moment from Little Boats for the Big Sailors","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.boita-bandana-5":{"src":"story:fk.boita-bandana:scenes:5:text","title":"Little Boats for the Big Sailors · 6 of 9","body":"The trade went both ways and left traces both ways. To this day, Bali — five thousand kilometres away in Indonesia — keeps its own festival remembering the old links with Kalinga, and Odia and Balinese scholars visit each other's festivals like distant cousins comparing family albums. The sea road is remembered at both ends.","art":"art/story/sm/fk-boita-bandana.jpg","route":"#/story/fk.boita-bandana|s5","cta":"Read from here","why":"A moment from Little Boats for the Big Sailors","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.boita-bandana-6":{"src":"story:fk.boita-bandana:scenes:6:text","title":"Little Boats for the Big Sailors · 7 of 9","body":"And in Cuttack, on the sands of the Mahanadi river, the little boats launch a giant fair: Bali Jatra — literally \"the journey to Bali\" — one of the biggest open-air fairs in India. For days there are stalls and wheels and toys and mountains of food, a whole city of celebration on the riverbank, all of it named for a voyage.","art":"art/story/sm/fk-boita-bandana.jpg","route":"#/story/fk.boita-bandana|s6","cta":"Read from here","why":"A moment from Little Boats for the Big Sailors","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.boita-bandana-7":{"src":"story:fk.boita-bandana:scenes:7:text","title":"Little Boats for the Big Sailors · 8 of 9","body":"The children who float boats at dawn mostly cannot sail a ship anywhere. That is not the point. The point is that a coastline remembers what it once did — and every lamp set on the water says: we have not forgotten that our great-great-grandparents crossed the sea.","art":"art/story/sm/fk-boita-bandana.jpg","route":"#/story/fk.boita-bandana|s7","cta":"Read from here","why":"A moment from Little Boats for the Big Sailors","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.manika-curd-1":{"src":"story:fk.manika-curd:scenes:1:text","title":"The Milkmaid and the Two Riders · 2 of 9","body":"Her name was Manika, and she sold curd — good thick curd from her own cows, with a brass pot and a coconut-shell ladle and a shady spot where the road ran near the lake. Armies, kings, pilgrims: everyone travels the same roads, and everyone gets thirsty on them.","art":"art/story/sm/fk-manika-curd.jpg","route":"#/story/fk.manika-curd|s1","cta":"Read from here","why":"A moment from The Milkmaid and the Two Riders","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.manika-curd-2":{"src":"story:fk.manika-curd:scenes:2:text","title":"The Milkmaid and the Two Riders · 3 of 9","body":"That hot afternoon, two riders came up the road ahead of all the rest — two brothers by the look of them, one dark as a rain cloud on a black... no — the tellings are exact about this: one rider dark, on a white horse; one fair, on a black horse; both of them beautiful, both of them dusty, both of them very thirsty indeed.","art":"art/story/sm/fk-manika-curd.jpg","route":"#/story/fk.manika-curd|s2","cta":"Read from here","why":"A moment from The Milkmaid and the Two Riders","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.manika-curd-3":{"src":"story:fk.manika-curd:scenes:3:text","title":"The Milkmaid and the Two Riders · 4 of 9","body":"\"Curd, mother,\" said the dark one, and she served them — bowl after bowl after bowl. They drank like men who had been riding for a hundred years. When at last they were done, the dark rider smiled, and — \"We have no coins with us. Take this. The king is coming up this road behind us; show it to him, and he will settle our account.\" And he gave her a ring.","art":"art/story/sm/fk-manika-curd.jpg","route":"#/story/fk.manika-curd|s3","cta":"Read from here","why":"A moment from The Milkmaid and the Two Riders","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.manika-curd-5":{"src":"story:fk.manika-curd:scenes:5:text","title":"The Milkmaid and the Two Riders · 6 of 9","body":"The army arrived — dust to the horizon, elephants, banners, and the king himself. Manika stepped up to the royal party, held out the ring, and said, simply: \"Two riders ahead of you drank curd at my stall, Maharaj. They said you would pay.\"","art":"art/story/sm/fk-manika-curd.jpg","route":"#/story/fk.manika-curd|s5","cta":"Read from here","why":"A moment from The Milkmaid and the Two Riders","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.manika-curd-6":{"src":"story:fk.manika-curd:scenes:6:text","title":"The Milkmaid and the Two Riders · 7 of 9","body":"The king took one look at the ring — and got down from his mount. For he knew it. It was from the temple at Puri; it was the Lord's own. And he understood what the tellings understand: that Jagannath and his brother Balabhadra themselves were riding ahead of his army, two brothers on a white horse and a black — and that they had stopped, like anyone, for curd at a good stall.","art":"art/story/sm/fk-manika-curd.jpg","route":"#/story/fk.manika-curd|s6","cta":"Read from here","why":"A moment from The Milkmaid and the Two Riders","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.manika-curd-7":{"src":"story:fk.manika-curd:scenes:7:text","title":"The Milkmaid and the Two Riders · 8 of 9","body":"The king paid Manika's account on the spot — and far more than the account. The tellings say he granted her village to her and her family; and to this day, near the Chilika lake, there is a place called Manikapatna — Manika's town — which Odia families will point out to you from the road.","art":"art/story/sm/fk-manika-curd.jpg","route":"#/story/fk.manika-curd|s7","cta":"Read from here","why":"A moment from The Milkmaid and the Two Riders","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.rasagola-door-1":{"src":"story:fk.rasagola-door:scenes:1:text","title":"The Sweet That Opened the Door · 2 of 8","body":"Nine days is a long trip. And here the tellings of Puri turn warm and domestic, because somebody did not go on the trip: Lakshmi, Jagannath's wife, goddess of fortune and of well-run households. She stayed home. For nine days. While her husband holidayed up the road with his brother and sister.","art":"art/story/sm/fk-rasagola-door.jpg","route":"#/story/fk.rasagola-door|s1","cta":"Read from here","why":"A moment from The Sweet That Opened the Door","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.rasagola-door-2":{"src":"story:fk.rasagola-door:scenes:2:text","title":"The Sweet That Opened the Door · 3 of 8","body":"The tellings are honest about her feelings, which is why everyone loves this story. Lakshmi waited. She counted the days. Somewhere around the middle of the nine, she went — in some tellings secretly, at night — up the road to look at the holiday from a distance. And then she came home, and thought, and made a decision.","art":"art/story/sm/fk-rasagola-door.jpg","route":"#/story/fk.rasagola-door|s2","cta":"Read from here","why":"A moment from The Sweet That Opened the Door","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.rasagola-door-3":{"src":"story:fk.rasagola-door:scenes:3:text","title":"The Sweet That Opened the Door · 4 of 8","body":"So the great procession came home — chariots, drums, conches, half of Odisha pulling the ropes — and rolled up to the temple, and the door was shut. The Lord of the Universe stood on his own doorstep. The drums trailed off. Somewhere inside, perfectly calm, fortune herself was waiting to hear what he had to say for himself.","art":"art/story/sm/fk-rasagola-door.jpg","route":"#/story/fk.rasagola-door|s3","cta":"Read from here","why":"A moment from The Sweet That Opened the Door","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.rasagola-door-5":{"src":"story:fk.rasagola-door:scenes:5:text","title":"The Sweet That Opened the Door · 6 of 8","body":"Lakshmi let him wait exactly as long as was instructive. Then she accepted the rasagolas — they were, to be fair, excellent — and named her terms: no more nine-day trips without proper regard for the one who keeps the house. Terms agreed. The door opened. The Lord of the Universe came home.","art":"art/story/sm/fk-rasagola-door.jpg","route":"#/story/fk.rasagola-door|s5","cta":"Read from here","why":"A moment from The Sweet That Opened the Door","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.rasagola-door-6":{"src":"story:fk.rasagola-door:scenes:6:text","title":"The Sweet That Opened the Door · 7 of 8","body":"And this is not just a story — it is on the temple calendar. The day Jagannath returns and makes peace at the door is called Niladri Bije, and rasagolas are offered that day, every single year. Odisha even keeps the date as Rasagola Dibasa — Rasagola Day — in honour of the sweet that opened the door.","art":"art/story/sm/fk-rasagola-door.jpg","route":"#/story/fk.rasagola-door|s6","cta":"Read from here","why":"A moment from The Sweet That Opened the Door","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.ridley-night-1":{"src":"story:fk.ridley-night:scenes:1:text","title":"The Night the Sea Comes Ashore · 2 of 8","body":"It begins as bumps in the surf line. Then more. Then more. Olive ridley sea turtles — small, round-shelled, the colour of wet olives — start walking out of the waves. Hundreds. Then thousands. Then tens of thousands, in a single night, until the beach is cobbled with turtles as far as a torch could shine, if anyone were unwise enough to shine one.","art":"art/story/sm/fk-ridley-night.jpg","route":"#/story/fk.ridley-night|s1","cta":"Read from here","why":"A moment from The Night the Sea Comes Ashore","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.ridley-night-2":{"src":"story:fk.ridley-night:scenes:2:text","title":"The Night the Sea Comes Ashore · 3 of 8","body":"Scientists use the Spanish word arribada — \"the arrival\" — for this, because only a few beaches in the whole world host it, and Odisha's are among the greatest. Every one of those turtles is a mother, and every one has swum from far across the ocean to this particular sand.","art":"art/story/sm/fk-ridley-night.jpg","route":"#/story/fk.ridley-night|s2","cta":"Read from here","why":"A moment from The Night the Sea Comes Ashore","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.ridley-night-3":{"src":"story:fk.ridley-night:scenes:3:text","title":"The Night the Sea Comes Ashore · 4 of 8","body":"Each mother hauls herself above the tide line, digs a neat flask-shaped nest with her back flippers — working blind, by instinct, like someone knitting behind their back — lays a hundred-odd soft white eggs, covers them, pats the sand down, and walks back into the sea. She will not return. The sand and the sun do the rest.","art":"art/story/sm/fk-ridley-night.jpg","route":"#/story/fk.ridley-night|s3","cta":"Read from here","why":"A moment from The Night the Sea Comes Ashore","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.ridley-night-5":{"src":"story:fk.ridley-night:scenes:5:text","title":"The Night the Sea Comes Ashore · 6 of 8","body":"So on hatching nights there are people on the beach in the dark, moving quietly: forest department staff, scientists with red-shaded torches, and villagers — including fishing families who set their nets differently in the nesting season so the mothers can pass. Odisha is proud of these turtles the way other places are proud of monuments.","art":"art/story/sm/fk-ridley-night.jpg","route":"#/story/fk.ridley-night|s5","cta":"Read from here","why":"A moment from The Night the Sea Comes Ashore","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.ridley-night-6":{"src":"story:fk.ridley-night:scenes:6:text","title":"The Night the Sea Comes Ashore · 7 of 8","body":"And the little ones that reach the waves swim out into the enormous ocean, and vanish for years. Then, grown, the females do the astonishing thing: they come back — across thousands of kilometres of trackless sea — to nest on the very coast where they hatched. How they navigate so exactly is still being studied; the answer is written somewhere in salt and magnetism and memory.","art":"art/story/sm/fk-ridley-night.jpg","route":"#/story/fk.ridley-night|s6","cta":"Read from here","why":"A moment from The Night the Sea Comes Ashore","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.tapoi-1":{"src":"story:fk.tapoi:scenes:1:text","title":"Tapoi and the Seven Ships · 2 of 9","body":"For a while, all was silk and sweets. But the months stretched, and no sail came back, and the household's money thinned — and six of the seven wives changed towards the little sister. The petting stopped. Then the kindness stopped. They dressed her in rags, fed her scraps, and sent her out to the scrubland every day to herd the goats.","art":"art/story/sm/fk-tapoi.jpg","route":"#/story/fk.tapoi|s1","cta":"Read from here","why":"A moment from Tapoi and the Seven Ships","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.tapoi-2":{"src":"story:fk.tapoi:scenes:2:text","title":"Tapoi and the Seven Ships · 3 of 9","body":"So Tapoi lived on the windy commons with the goats and the mynah birds, the merchant's pearl turned goatherd. And there, in the month of Bhadraba, she saw village girls gathering on Sundays with offerings of khuda — broken rice, the humblest grain there is — to worship the goddess Mangala, keeper of those who wait.","art":"art/story/sm/fk-tapoi.jpg","route":"#/story/fk.tapoi|s2","cta":"Read from here","why":"A moment from Tapoi and the Seven Ships","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.tapoi-3":{"src":"story:fk.tapoi:scenes:3:text","title":"Tapoi and the Seven Ships · 4 of 9","body":"Tapoi had nothing: no silk, no sweets, not a whole grain of rice to her name. Only broken rice, gathered from what was thrown to the goats.","art":"art/story/sm/fk-tapoi.jpg","route":"#/story/fk.tapoi|s3","cta":"Read from here","why":"A moment from Tapoi and the Seven Ships","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.tapoi-5":{"src":"story:fk.tapoi:scenes:5:text","title":"Tapoi and the Seven Ships · 6 of 9","body":"And one morning the horizon grew sails. Seven of them. The seven ships came up the river laden to the waterline — the voyage had been long because it had been lucky — and the seven brothers stepped ashore asking, first thing, for their little sister.","art":"art/story/sm/fk-tapoi.jpg","route":"#/story/fk.tapoi|s5","cta":"Read from here","why":"A moment from Tapoi and the Seven Ships","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.tapoi-6":{"src":"story:fk.tapoi:scenes:6:text","title":"Tapoi and the Seven Ships · 7 of 9","body":"The six wives flew to dress Tapoi in silk and undo six months of cruelty in six minutes. But truth walks faster than silk. The whole story came out — the rags, the scraps, the goats — the youngest wife's kindness shining out of it like a lamp.","art":"art/story/sm/fk-tapoi.jpg","route":"#/story/fk.tapoi|s6","cta":"Read from here","why":"A moment from Tapoi and the Seven Ships","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.tapoi-7":{"src":"story:fk.tapoi:scenes:7:text","title":"Tapoi and the Seven Ships · 8 of 9","body":"The oldest tellings deal harshly with the six wives, and the source below says so honestly. Told gently: they were made to stand before the whole household and hear the truth said out loud, and to serve Tapoi as she had been made to serve — until they understood it from the inside. Shame that teaches is worth more than punishment that doesn't. The seventh wife was honoured above them all.","art":"art/story/sm/fk-tapoi.jpg","route":"#/story/fk.tapoi|s7","cta":"Read from here","why":"A moment from Tapoi and the Seven Ships","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.lalkamal-nilkamal-1":{"src":"story:fk.lalkamal-nilkamal:scenes:1:text","title":"Lalkamal and Nilkamal · 2 of 9","body":"Each queen had a son. The rakkhosh-queen's boy was Lalkamal, the red lotus; the human queen's boy was Nilkamal, the blue lotus. And here is the lovely part: the two half-brothers loved each other completely. Same games, same lessons, same mischief; you never saw one without the other close behind.","art":"art/story/sm/fk-lalkamal-nilkamal.jpg","route":"#/story/fk.lalkamal-nilkamal|s1","cta":"Read from here","why":"A moment from Lalkamal and Nilkamal","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.lalkamal-nilkamal-2":{"src":"story:fk.lalkamal-nilkamal:scenes:2:text","title":"Lalkamal and Nilkamal · 3 of 9","body":"But at night, rakkhosh relatives came sniffing round the palace — and a rakkhosh announces itself from a mile off, because it cannot help bellowing the family motto: \"Haau maau khaau! Manusher gawndho paau!\" — which is Bengali for roughly \"Fee! Fo! Yum! I smell a hu-man!\" Rakkhosh are extremely dangerous and extremely bad at being sneaky, both at once.","art":"art/story/sm/fk-lalkamal-nilkamal.jpg","route":"#/story/fk.lalkamal-nilkamal|s2","cta":"Read from here","why":"A moment from Lalkamal and Nilkamal","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.lalkamal-nilkamal-3":{"src":"story:fk.lalkamal-nilkamal:scenes:3:text","title":"Lalkamal and Nilkamal · 4 of 9","body":"The brothers learned the danger was creeping close, and did what heroes in Thakurmar Jhuli do: they saddled two horses and rode out to end it — all the way to the rakkhosh kingdom itself. There they took a room in the ogre-king's own guest house, and agreed to keep watch in turns: one sleeps, one guards, and the guard must NOT fall asleep.","art":"art/story/sm/fk-lalkamal-nilkamal.jpg","route":"#/story/fk.lalkamal-nilkamal|s3","cta":"Read from here","why":"A moment from Lalkamal and Nilkamal","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.lalkamal-nilkamal-5":{"src":"story:fk.lalkamal-nilkamal:scenes:5:text","title":"Lalkamal and Nilkamal · 6 of 9","body":"At dawn the brothers found the tank. Nilkamal dived — down and down through the cold green water — and came up gasping with the box in his hands. Inside, two golden bees buzzed furiously, and every rakkhosh in the kingdom sat bolt upright at once, feeling something go wobbly in the world.","art":"art/story/sm/fk-lalkamal-nilkamal.jpg","route":"#/story/fk.lalkamal-nilkamal|s5","cta":"Read from here","why":"A moment from Lalkamal and Nilkamal","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.lalkamal-nilkamal-6":{"src":"story:fk.lalkamal-nilkamal:scenes:6:text","title":"Lalkamal and Nilkamal · 7 of 9","body":"Rakkhosh came thundering from every direction, roaring their haau-maau-khaau — and Lalkamal held up the box, and the whole army skidded to a halt, suddenly as polite as aunties at a wedding. \"Careful with that,\" said the ogre-king, in a small voice.","art":"art/story/sm/fk-lalkamal-nilkamal.jpg","route":"#/story/fk.lalkamal-nilkamal|s6","cta":"Read from here","why":"A moment from Lalkamal and Nilkamal","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.lalkamal-nilkamal-7":{"src":"story:fk.lalkamal-nilkamal:scenes:7:text","title":"Lalkamal and Nilkamal · 8 of 9","body":"The brothers rode home to both their mothers, and the palace slept soundly at night, at last. And what everyone remembered afterwards was not the bees or the diving, but the simplest thing: neither brother, at any point, in any danger, had even once considered leaving without the other.","art":"art/story/sm/fk-lalkamal-nilkamal.jpg","route":"#/story/fk.lalkamal-nilkamal|s7","cta":"Read from here","why":"A moment from Lalkamal and Nilkamal","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.gopal-pot-of-wit-1":{"src":"story:fk.gopal-pot-of-wit:scenes:1:text","title":"A Pot Full of Cleverness · 2 of 9","body":"One day a visiting pandit sniffed that the Raja's court was rich in gold but poor in brains, and the Raja, stung, decided to out-clever everyone at once. \"Gopal!\" he announced before the full court. \"You are said to be the wittiest man in Bengal. Prove it. Bring me a pot full of buddhi — a pot full of wit — by the next full moon. Fail, and we shall know your cleverness was only talk.\"","art":"art/story/sm/fk-gopal-pot-of-wit.jpg","route":"#/story/fk.gopal-pot-of-wit|s1","cta":"Read from here","why":"A moment from A Pot Full of Cleverness","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.gopal-pot-of-wit-2":{"src":"story:fk.gopal-pot-of-wit:scenes:2:text","title":"A Pot Full of Cleverness · 3 of 9","body":"The court tittered. You cannot pour cleverness out of a jug; everyone knew Gopal was beaten at last. Gopal, however, bowed deeply, went home... and out in his vegetable patch, planted one gourd seed beside a narrow-necked clay pot.","art":"art/story/sm/fk-gopal-pot-of-wit.jpg","route":"#/story/fk.gopal-pot-of-wit|s2","cta":"Read from here","why":"A moment from A Pot Full of Cleverness","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.gopal-pot-of-wit-3":{"src":"story:fk.gopal-pot-of-wit:scenes:3:text","title":"A Pot Full of Cleverness · 4 of 9","body":"The vine climbed, and Gopal trained one baby gourd — small as your thumb — in through the pot's narrow neck. And there, in the dark of the pot, fed by its vine through the neck, the gourd grew. And grew. Until it filled every curve of the inside, snug as a fist in a glove.","art":"art/story/sm/fk-gopal-pot-of-wit.jpg","route":"#/story/fk.gopal-pot-of-wit|s3","cta":"Read from here","why":"A moment from A Pot Full of Cleverness","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.gopal-pot-of-wit-5":{"src":"story:fk.gopal-pot-of-wit:scenes:5:text","title":"A Pot Full of Cleverness · 6 of 9","body":"The Raja reached in. The gourd would not come — the neck was far too narrow. He turned the pot over. He shook it. He went a delicate shade of pink. \"It does not come OUT, Gopal.\" \"No, Maharaj,\" said Gopal, beaming. \"That is the thing about buddhi. Easy to put into a young head. From a grown one, it does not pour.\"","art":"art/story/sm/fk-gopal-pot-of-wit.jpg","route":"#/story/fk.gopal-pot-of-wit|s5","cta":"Read from here","why":"A moment from A Pot Full of Cleverness","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.gopal-pot-of-wit-6":{"src":"story:fk.gopal-pot-of-wit:scenes:6:text","title":"A Pot Full of Cleverness · 7 of 9","body":"\"And that, Maharaj,\" Gopal went on, warming up nicely, \"is why it must be grown — slowly, in the dark, unseen, from one small seed. Anyone who promises you a pot of ready-made wit,\" and here he bowed very slightly towards the visiting pandit, \"is selling you an empty pot.\"","art":"art/story/sm/fk-gopal-pot-of-wit.jpg","route":"#/story/fk.gopal-pot-of-wit|s6","cta":"Read from here","why":"A moment from A Pot Full of Cleverness","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.gopal-pot-of-wit-7":{"src":"story:fk.gopal-pot-of-wit:scenes:7:text","title":"A Pot Full of Cleverness · 8 of 9","body":"The Raja laughed until his crown slipped, paid Gopal his weight in — well, in sweets, this being Bengal — and kept the pot on display in the court. Whenever anyone boasted of their brains thereafter, Krishnachandra would silently point at it.","art":"art/story/sm/fk-gopal-pot-of-wit.jpg","route":"#/story/fk.gopal-pot-of-wit|s7","cta":"Read from here","why":"A moment from A Pot Full of Cleverness","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.bonbibi-dukhey-1":{"src":"story:fk.bonbibi-dukhey:scenes:1:text","title":"Bonbibi, Lady of the Forest · 2 of 10","body":"Before the boats slip into the forest rivers, the honey-gatherers — the moule, as they are called — say a name: Bonbibi. The lady of the forest. And here is the wonder of her: the Hindu families say it and the Muslim families say it, together, in the same boats.","art":"art/story/sm/fk-bonbibi-dukhey.jpg","route":"#/story/fk.bonbibi-dukhey|s1","cta":"Read from here","why":"A moment from Bonbibi, Lady of the Forest","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.bonbibi-dukhey-2":{"src":"story:fk.bonbibi-dukhey:scenes:2:text","title":"Bonbibi, Lady of the Forest · 3 of 10","body":"The forest also has an older power: Dokkhin Rai, lord of the south, who rides in the shape of the great tiger. He is not a monster — say that clearly. He is the forest's own fierce majesty, honoured in his own right at forest shrines; but his anger burns against human greed, and when people take too much from his forest, his justice is terrible.","art":"art/story/sm/fk-bonbibi-dukhey.jpg","route":"#/story/fk.bonbibi-dukhey|s2","cta":"Read from here","why":"A moment from Bonbibi, Lady of the Forest","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.bonbibi-dukhey-3":{"src":"story:fk.bonbibi-dukhey:scenes:3:text","title":"Bonbibi, Lady of the Forest · 4 of 10","body":"A greedy trader named Dhona fitted out seven boats for honey, and — because the tale must have its shame — brought along a poor widow's young son, Dukhey, whose name means sorrow.","art":"art/story/sm/fk-bonbibi-dukhey.jpg","route":"#/story/fk.bonbibi-dukhey|s3","cta":"Read from here","why":"A moment from Bonbibi, Lady of the Forest","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.bonbibi-dukhey-4":{"src":"story:fk.bonbibi-dukhey:scenes:4:text","title":"Bonbibi, Lady of the Forest · 5 of 10","body":"Dukhey stood alone on the bank as the boats grew small, and the forest grew large, and somewhere in the mangroves something golden and striped began to move. And the boy did the one thing his mother had taught him before he sailed: \"If you are ever lost past hope in the forest, call Ma Bonbibi. She comes.\"","art":"art/story/sm/fk-bonbibi-dukhey.jpg","route":"#/story/fk.bonbibi-dukhey|s4","cta":"Read from here","why":"A moment from Bonbibi, Lady of the Forest","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.bonbibi-dukhey-6":{"src":"story:fk.bonbibi-dukhey:scenes:6:text","title":"Bonbibi, Lady of the Forest · 7 of 10","body":"And the terms are the whole treasure of the story. The forest was shared out: the deep wild places for Dokkhin Rai and his creatures, forever; the edges for the people — and the people may enter ONLY needing, never merely wanting. Come with a clean heart and empty hands, take just what your family needs, waste nothing, and Bonbibi walks with you. Come greedy, and you walk alone.","art":"art/story/sm/fk-bonbibi-dukhey.jpg","route":"#/story/fk.bonbibi-dukhey|s6","cta":"Read from here","why":"A moment from Bonbibi, Lady of the Forest","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.bonbibi-dukhey-7":{"src":"story:fk.bonbibi-dukhey:scenes:7:text","title":"Bonbibi, Lady of the Forest · 8 of 10","body":"Dukhey was carried home — the tellings say on the back of a great crocodile, which is the best school-run in all of Bengali literature — with wealth enough to keep his mother forever. Dhona's shame was told in every market. And to this day the moule keep the terms: they enter quietly, take modestly, and never boast, for the honey is the forest's gift, not their conquest.","art":"art/story/sm/fk-bonbibi-dukhey.jpg","route":"#/story/fk.bonbibi-dukhey|s7","cta":"Read from here","why":"A moment from Bonbibi, Lady of the Forest","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.bonbibi-dukhey-8":{"src":"story:fk.bonbibi-dukhey:scenes:8:text","title":"Bonbibi, Lady of the Forest · 9 of 10","body":"And the tiger stays the tiger — never hunted in the tale, never hated. The forest people's word for him is respect: he is why the deep forest stays deep, why no one takes too much, why the Sundarbans is still standing when so many forests are gone. A guarded forest needs its guard to be genuinely formidable.","art":"art/story/sm/fk-bonbibi-dukhey.jpg","route":"#/story/fk.bonbibi-dukhey|s8","cta":"Read from here","why":"A moment from Bonbibi, Lady of the Forest","facts":[["From","East & the Islands"],["Read","5 min"]]},"ss-fk.ilish-rain-1":{"src":"story:fk.ilish-rain:scenes:1:text","title":"The Fish That Comes With the Rain · 2 of 8","body":"The ilish — hilsa, in English — is a silver fish that lives in the sea. But when the rains swell the rivers, the ilish do an extraordinary thing: they leave the sea in their gleaming thousands and swim UP the rivers — up the Hooghly, up the wide mouths of the delta — against the current, into the very heart of Bengal, as their kind has done since before there was a Bengal to swim into.","art":"art/story/sm/fk-ilish-rain.jpg","route":"#/story/fk.ilish-rain|s1","cta":"Read from here","why":"A moment from The Fish That Comes With the Rain","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.ilish-rain-2":{"src":"story:fk.ilish-rain:scenes:2:text","title":"The Fish That Comes With the Rain · 3 of 8","body":"The fishing families read the signs like a letter: the colour of the clouds, the smell of the wind off the water, the day the river turns just so. Then the boats go out in the grey rain — small boats, big nets, generations of knowing — because sea-ilish is good, but river-ilish, plumped on the monsoon rivers, is the one the poets meant.","art":"art/story/sm/fk-ilish-rain.jpg","route":"#/story/fk.ilish-rain|s2","cta":"Read from here","why":"A moment from The Fish That Comes With the Rain","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.ilish-rain-3":{"src":"story:fk.ilish-rain:scenes:3:text","title":"The Fish That Comes With the Rain · 4 of 8","body":"And in the markets — oh, the markets in ilish season. The silver rows on the ice. The connoisseurs bending over them like jewellers, checking the gleam of a gill, arguing Padma-side versus Hooghly-side like rival football fans. Grandmothers who trust no one under sixty to choose a fish. It is not shopping; it is theatre with scales on.","art":"art/story/sm/fk-ilish-rain.jpg","route":"#/story/fk.ilish-rain|s3","cta":"Read from here","why":"A moment from The Fish That Comes With the Rain","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.ilish-rain-5":{"src":"story:fk.ilish-rain:scenes:5:text","title":"The Fish That Comes With the Rain · 6 of 8","body":"So today there are rules, kept better and better: no netting the tiniest ilish, rest periods when the mother fish run upriver to spawn. Fishing families grumble and comply and mostly agree — nobody wants to be the generation that ate the last one. Loving a fish properly, it turns out, includes leaving it alone at the right times.","art":"art/story/sm/fk-ilish-rain.jpg","route":"#/story/fk.ilish-rain|s5","cta":"Read from here","why":"A moment from The Fish That Comes With the Rain","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.ilish-rain-6":{"src":"story:fk.ilish-rain:scenes:6:text","title":"The Fish That Comes With the Rain · 7 of 8","body":"And when the season's first proper ilish reaches a family kitchen — steamed with mustard, or fried crisp with a mountain of rice while the rain hammers the windows — Bengal is, for one meal, entirely at peace. Across the border in Bangladesh it is the national fish, and the arguing over whose rivers make the better ilish is itself a beloved regional sport, played at every wedding.","art":"art/story/sm/fk-ilish-rain.jpg","route":"#/story/fk.ilish-rain|s6","cta":"Read from here","why":"A moment from The Fish That Comes With the Rain","facts":[["From","East & the Islands"],["Read","4 min"]]},"ss-fk.warli-chauk-1":{"src":"story:fk.warli-chauk:scenes:1:text","title":"The Painting Made of Rice · 2 of 8","body":"Not with shop paint. With rice. Rice ground to powder, mixed with water into a white paste, put on with a chewed bamboo twig for a brush. White rice pictures on a red-brown wall — people, trees, birds, whole villages, all made of circles and triangles and lines.","art":"art/story/sm/fk-warli-chauk.jpg","route":"#/story/fk.warli-chauk|s1","cta":"Read from here","why":"A moment from The Painting Made of Rice","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.warli-chauk-2":{"src":"story:fk.warli-chauk:scenes:2:text","title":"The Painting Made of Rice · 3 of 8","body":"A visitor once asked a Warli grandmother why the pictures were so simple. She looked at him for a while. \"A circle is the sun and the moon,\" she said. \"A triangle is a mountain and a tree. What else is there? You tell me one thing that is not in my painting.\"","art":"art/story/sm/fk-warli-chauk.jpg","route":"#/story/fk.warli-chauk|s2","cta":"Read from here","why":"A moment from The Painting Made of Rice","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.warli-chauk-3":{"src":"story:fk.warli-chauk:scenes:3:text","title":"The Painting Made of Rice · 4 of 8","body":"The most important painting of all is the chauk — the square. When there is a wedding, the married women of the family paint a big square on the wall, and inside it goes Palaghata, the goddess of the marriage, and around her the whole world: the sun, the comb, the ladder, the people.","art":"art/story/sm/fk-warli-chauk.jpg","route":"#/story/fk.warli-chauk|s3","cta":"Read from here","why":"A moment from The Painting Made of Rice","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.warli-chauk-5":{"src":"story:fk.warli-chauk:scenes:5:text","title":"The Painting Made of Rice · 6 of 8","body":"The paintings are not signed and they are not sold off the wall. When the wall is mended, the painting goes, and a new one is made for the next wedding, the next harvest. The picture is not the point. The making of it, together, is the point.","art":"art/story/sm/fk-warli-chauk.jpg","route":"#/story/fk.warli-chauk|s5","cta":"Read from here","why":"A moment from The Painting Made of Rice","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.warli-chauk-6":{"src":"story:fk.warli-chauk:scenes:6:text","title":"The Painting Made of Rice · 7 of 8","body":"These days Warli painting is famous far beyond the hills — on cloth, in galleries, in faraway cities. And Warli artists will tell you, politely but firmly: it is not a pattern, it is ours. It has a home, and the home has a name.","art":"art/story/sm/fk-warli-chauk.jpg","route":"#/story/fk.warli-chauk|s6","cta":"Read from here","why":"A moment from The Painting Made of Rice","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.warli-tarpa-1":{"src":"story:fk.warli-tarpa:scenes:1:text","title":"Why the Dance Goes Round · 2 of 8","body":"And the village comes. Everyone — grandmothers, farmers, children who can barely walk — takes the hand of the next person, and the line begins to move around the tarpa player. Round, and round, coiling in and uncoiling out, like a creeper growing.","art":"art/story/sm/fk-warli-tarpa.jpg","route":"#/story/fk.warli-tarpa|s1","cta":"Read from here","why":"A moment from Why the Dance Goes Round","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.warli-tarpa-2":{"src":"story:fk.warli-tarpa:scenes:2:text","title":"Why the Dance Goes Round · 3 of 8","body":"A boy once asked his grandfather, \"Why in a circle? In the town they dance facing the front, where everyone can see them.\" His grandfather kept dancing, because you can talk and dance at the same time if the dance is kind. \"Look at the line, and tell me who is first in it,\" he said.","art":"art/story/sm/fk-warli-tarpa.jpg","route":"#/story/fk.warli-tarpa|s2","cta":"Read from here","why":"A moment from Why the Dance Goes Round","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.warli-tarpa-3":{"src":"story:fk.warli-tarpa:scenes:3:text","title":"Why the Dance Goes Round · 4 of 8","body":"The boy looked. The line curled round and round the tarpa player. The end held hands with the middle, the middle with the beginning.","art":"art/story/sm/fk-warli-tarpa.jpg","route":"#/story/fk.warli-tarpa|s3","cta":"Read from here","why":"A moment from Why the Dance Goes Round","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.warli-tarpa-5":{"src":"story:fk.warli-tarpa:scenes:5:text","title":"Why the Dance Goes Round · 6 of 8","body":"The tarpa player stands in the middle and cannot stop, because the moment the horn stops the dance stops, so he plays until his breath is done and another player slides in and takes over without a gap — the way you pass a full bowl carefully, so nothing spills.","art":"art/story/sm/fk-warli-tarpa.jpg","route":"#/story/fk.warli-tarpa|s5","cta":"Read from here","why":"A moment from Why the Dance Goes Round","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.warli-tarpa-6":{"src":"story:fk.warli-tarpa:scenes:6:text","title":"Why the Dance Goes Round · 7 of 8","body":"They dance for the harvest, and for the gods of the green, and because it is the time of year for it. And a child who joins the line learns the whole thing without one lesson — the steps travel down the line, hand to hand, into their feet.","art":"art/story/sm/fk-warli-tarpa.jpg","route":"#/story/fk.warli-tarpa|s6","cta":"Read from here","why":"A moment from Why the Dance Goes Round","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.waghoba-watch-1":{"src":"story:fk.waghoba-watch:scenes:1:text","title":"The Tiger Who Keeps Watch · 2 of 8","body":"Waghoba is the tiger god, the big one, the lord of everything with paws and stripes. The forest is his house. The village is the people's house. And the shrine stands exactly on the doorstep between the two, because that is where a watchman stands.","art":"art/story/sm/fk-waghoba-watch.jpg","route":"#/story/fk.waghoba-watch|s1","cta":"Read from here","why":"A moment from The Tiger Who Keeps Watch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.waghoba-watch-2":{"src":"story:fk.waghoba-watch:scenes:2:text","title":"The Tiger Who Keeps Watch · 3 of 8","body":"A girl once asked her grandmother, \"Why do we give offerings to the tiger? Shouldn't we hide from him instead?\" Her grandmother was arranging rice and a marigold at the shrine, and she did not hurry her answer.","art":"art/story/sm/fk-waghoba-watch.jpg","route":"#/story/fk.waghoba-watch|s2","cta":"Read from here","why":"A moment from The Tiger Who Keeps Watch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.waghoba-watch-3":{"src":"story:fk.waghoba-watch:scenes:3:text","title":"The Tiger Who Keeps Watch · 4 of 8","body":"\"When your uncle visits,\" she said, \"we feed him and speak to him with respect, and so he is family and not a stranger. It is the same with the forest. Waghoba is our biggest neighbour. You do not hide from a neighbour. You greet him properly, and then you both know how to behave.\"","art":"art/story/sm/fk-waghoba-watch.jpg","route":"#/story/fk.waghoba-watch|s3","cta":"Read from here","why":"A moment from The Tiger Who Keeps Watch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.waghoba-watch-5":{"src":"story:fk.waghoba-watch:scenes:5:text","title":"The Tiger Who Keeps Watch · 6 of 8","body":"At harvest time the village goes to the shrine together. The offerings are simple — rice, a coconut, a daub of red — and the asking is simple too: keep to your side, we will keep to ours, and let neither house trouble the other.","art":"art/story/sm/fk-waghoba-watch.jpg","route":"#/story/fk.waghoba-watch|s5","cta":"Read from here","why":"A moment from The Tiger Who Keeps Watch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.waghoba-watch-6":{"src":"story:fk.waghoba-watch:scenes:6:text","title":"The Tiger Who Keeps Watch · 7 of 8","body":"Scientists who study big cats in these hills have noticed something worth noticing: villages that keep Waghoba's shrine tend to speak of leopards with respect instead of panic. The old agreement still works, both ways.","art":"art/story/sm/fk-waghoba-watch.jpg","route":"#/story/fk.waghoba-watch|s6","cta":"Read from here","why":"A moment from The Tiger Who Keeps Watch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kansari-grain-1":{"src":"story:fk.kansari-grain:scenes:1:text","title":"Kansari and the Last Handful · 2 of 8","body":"A girl was helping her grandmother carry rice to the cooking fire when the basket tipped, and a small white spray of grains went into the dust. She was going to sweep them out of the door. Her grandmother caught her hand.","art":"art/story/sm/fk-kansari-grain.jpg","route":"#/story/fk.kansari-grain|s1","cta":"Read from here","why":"A moment from Kansari and the Last Handful","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kansari-grain-2":{"src":"story:fk.kansari-grain:scenes:2:text","title":"Kansari and the Last Handful · 3 of 8","body":"\"Pick them up,\" said her grandmother. \"Every one.\" And she got down on her knees, old as she was, and began picking grains out of the dust with her fingertips, one by one, as carefully as if they were beads from a necklace.","art":"art/story/sm/fk-kansari-grain.jpg","route":"#/story/fk.kansari-grain|s2","cta":"Read from here","why":"A moment from Kansari and the Last Handful","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kansari-grain-3":{"src":"story:fk.kansari-grain:scenes:3:text","title":"Kansari and the Last Handful · 4 of 8","body":"\"Aaji, it is only a handful,\" said the girl. \"We have a whole basket.\" Her grandmother sat back and looked at her, and the girl understood that she had said something important without knowing what.","art":"art/story/sm/fk-kansari-grain.jpg","route":"#/story/fk.kansari-grain|s3","cta":"Read from here","why":"A moment from Kansari and the Last Handful","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kansari-grain-5":{"src":"story:fk.kansari-grain:scenes:5:text","title":"Kansari and the Last Handful · 6 of 8","body":"But in a house where every grain is treated as a guest — gathered up, stored dry, cooked with attention, shared without grudging — Kansari settles in like a grandmother by the fire, and the pot in that house somehow always stretches to one more person.","art":"art/story/sm/fk-kansari-grain.jpg","route":"#/story/fk.kansari-grain|s5","cta":"Read from here","why":"A moment from Kansari and the Last Handful","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kansari-grain-6":{"src":"story:fk.kansari-grain:scenes:6:text","title":"Kansari and the Last Handful · 7 of 8","body":"When the harvest comes in, the villages honour her properly — the first of the new grain is hers before anyone else eats. Not because she is fierce. Because she is the mother, and the mother is served first.","art":"art/story/sm/fk-kansari-grain.jpg","route":"#/story/fk.kansari-grain|s6","cta":"Read from here","why":"A moment from Kansari and the Last Handful","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.damanganga-winds-1":{"src":"story:fk.damanganga-winds:scenes:1:text","title":"The River That Would Not Hurry · 2 of 8","body":"This is the story one grandfather told about it, sitting on the bank with his feet in the water, and he told it as if he had been there.","art":"art/story/sm/fk-damanganga-winds.jpg","route":"#/story/fk.damanganga-winds|s1","cta":"Read from here","why":"A moment from The River That Would Not Hurry","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.damanganga-winds-2":{"src":"story:fk.damanganga-winds:scenes:2:text","title":"The River That Would Not Hurry · 3 of 8","body":"When the river first came down from the hills, young and quick, she meant to run straight to the sea. But at the first village a farmer called out: \"Sister! My fields are dry — could you come just a little this way?\" And she thought, well, it is hardly out of my path, and she bent towards him.","art":"art/story/sm/fk-damanganga-winds.jpg","route":"#/story/fk.damanganga-winds|s2","cta":"Read from here","why":"A moment from The River That Would Not Hurry","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.damanganga-winds-3":{"src":"story:fk.damanganga-winds:scenes:3:text","title":"The River That Would Not Hurry · 4 of 8","body":"At the next village the buffaloes were standing in the heat with their tongues out, and she bent again. Then a grove of old mango trees. Then a washing stone. Then a fishing village that would have no fish without her. Each time only a little bend. Only a little.","art":"art/story/sm/fk-damanganga-winds.jpg","route":"#/story/fk.damanganga-winds|s3","cta":"Read from here","why":"A moment from The River That Would Not Hurry","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.damanganga-winds-5":{"src":"story:fk.damanganga-winds:scenes:5:text","title":"The River That Would Not Hurry · 6 of 8","body":"So the map is the story. Every bend in the Daman Ganga is a place where somebody once called out and the river answered. The straight path was there all along. She chose the useful one.","art":"art/story/sm/fk-damanganga-winds.jpg","route":"#/story/fk.damanganga-winds|s5","cta":"Read from here","why":"A moment from The River That Would Not Hurry","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.damanganga-winds-6":{"src":"story:fk.damanganga-winds:scenes:6:text","title":"The River That Would Not Hurry · 7 of 8","body":"And it is true today in the plainest way: the river's water works for the fields, the villages and the towns of this small green territory before one drop of it reaches the sea. Ask anyone who farms beside her.","art":"art/story/sm/fk-damanganga-winds.jpg","route":"#/story/fk.damanganga-winds|s6","cta":"Read from here","why":"A moment from The River That Would Not Hurry","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kokna-honey-1":{"src":"story:fk.kokna-honey:scenes:1:text","title":"Half for the Bees · 2 of 8","body":"A boy went honey-gathering with his uncle for the first time. They went early, with smoke to make the bees sleepy and a basket lined with leaves, and his uncle climbed like a man who had done it a hundred times, because he had.","art":"art/story/sm/fk-kokna-honey.jpg","route":"#/story/fk.kokna-honey|s1","cta":"Read from here","why":"A moment from Half for the Bees","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kokna-honey-2":{"src":"story:fk.kokna-honey:scenes:2:text","title":"Half for the Bees · 3 of 8","body":"The comb was enormous — golden, heavy, big as a winnowing tray. The boy's mouth watered all the way from the ground. \"Take it all, kaka!\" he called up. \"Look at the size of it!\"","art":"art/story/sm/fk-kokna-honey.jpg","route":"#/story/fk.kokna-honey|s2","cta":"Read from here","why":"A moment from Half for the Bees","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kokna-honey-3":{"src":"story:fk.kokna-honey:scenes:3:text","title":"Half for the Bees · 4 of 8","body":"His uncle looked at the comb for a moment. Then he took out his knife and cut — not the whole comb. Half. He left the other half hanging where it was, bees and all, and came down.","art":"art/story/sm/fk-kokna-honey.jpg","route":"#/story/fk.kokna-honey|s3","cta":"Read from here","why":"A moment from Half for the Bees","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kokna-honey-5":{"src":"story:fk.kokna-honey:scenes:5:text","title":"Half for the Bees · 6 of 8","body":"\"Who taught you all the rules?\" asked the boy. \"My uncle,\" said his uncle. \"And him, his uncle. Nobody remembers who was first. The forest taught the first one, probably — by going empty on somebody who was greedy.\"","art":"art/story/sm/fk-kokna-honey.jpg","route":"#/story/fk.kokna-honey|s5","cta":"Read from here","why":"A moment from Half for the Bees","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kokna-honey-6":{"src":"story:fk.kokna-honey:scenes:6:text","title":"Half for the Bees · 7 of 8","body":"And the proof of the rules walks about in the forest to this day: the Kokna have gathered honey from these hills for generations beyond counting, and the hills still hum with bees. Both things are true at once. That is the whole trick of it.","art":"art/story/sm/fk-kokna-honey.jpg","route":"#/story/fk.kokna-honey|s6","cta":"Read from here","why":"A moment from Half for the Bees","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.dhodia-road-1":{"src":"story:fk.dhodia-road:scenes:1:text","title":"The Road the Grandmothers Remember · 2 of 8","body":"A girl sat with her grandmother at a family gathering, the kind where the old people talk late, and asked the question children always ask sooner or later: \"Aaji, where are we from?\"","art":"art/story/sm/fk-dhodia-road.jpg","route":"#/story/fk.dhodia-road|s1","cta":"Read from here","why":"A moment from The Road the Grandmothers Remember","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.dhodia-road-2":{"src":"story:fk.dhodia-road:scenes:2:text","title":"The Road the Grandmothers Remember · 3 of 8","body":"Her grandmother did not say the name of their village, though they had lived in it for four generations. She said, \"We came. The old people walked, with their seed-grain tied up safe and their gods carried carefully, and they crossed the rivers, and they came down into this green country, and it was good, and they stayed.\"","art":"art/story/sm/fk-dhodia-road.jpg","route":"#/story/fk.dhodia-road|s2","cta":"Read from here","why":"A moment from The Road the Grandmothers Remember","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.dhodia-road-3":{"src":"story:fk.dhodia-road:scenes:3:text","title":"The Road the Grandmothers Remember · 4 of 8","body":"\"But that was so long ago,\" said the girl. \"Before your grandmother's grandmother. Why do we still tell it? Nobody remembers the actual road.\"","art":"art/story/sm/fk-dhodia-road.jpg","route":"#/story/fk.dhodia-road|s3","cta":"Read from here","why":"A moment from The Road the Grandmothers Remember","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.dhodia-road-5":{"src":"story:fk.dhodia-road:scenes:5:text","title":"The Road the Grandmothers Remember · 6 of 8","body":"The girl looked around the gathering — the food, the talk, the little ones asleep in laps — and understood that she was sitting inside everything the walkers had carried. The road had ended generations ago. The luggage was still being used every day.","art":"art/story/sm/fk-dhodia-road.jpg","route":"#/story/fk.dhodia-road|s5","cta":"Read from here","why":"A moment from The Road the Grandmothers Remember","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.dhodia-road-6":{"src":"story:fk.dhodia-road:scenes:6:text","title":"The Road the Grandmothers Remember · 7 of 8","body":"Many peoples of India carry a journey-memory like this one, each their own. It is a particular kind of treasure: a story that says, we were travellers once, and look — we built all this.","art":"art/story/sm/fk-dhodia-road.jpg","route":"#/story/fk.dhodia-road|s6","cta":"Read from here","why":"A moment from The Road the Grandmothers Remember","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.hirwa-green-1":{"src":"story:fk.hirwa-green:scenes:1:text","title":"Hirwa of the Green · 2 of 8","body":"But the Warli know whose month is coming. Among their gods is Hirwa — the green one, the god of growing things, of the sprouting seed and the leafing tree and everything the rain wakes up. The brown months are simply Hirwa away on a journey.","art":"art/story/sm/fk-hirwa-green.jpg","route":"#/story/fk.hirwa-green|s1","cta":"Read from here","why":"A moment from Hirwa of the Green","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.hirwa-green-2":{"src":"story:fk.hirwa-green:scenes:2:text","title":"Hirwa of the Green · 3 of 8","body":"A boy asked his father, in the worst of the heat, \"What if he does not come back this year?\" His father was mending the plough, getting ready, which is itself a kind of answer. \"He has come back every year since the first year,\" he said. \"But it is right to ask him properly, all the same.\"","art":"art/story/sm/fk-hirwa-green.jpg","route":"#/story/fk.hirwa-green|s2","cta":"Read from here","why":"A moment from Hirwa of the Green","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.hirwa-green-3":{"src":"story:fk.hirwa-green:scenes:3:text","title":"Hirwa of the Green · 4 of 8","body":"So before the sowing, the village honours Hirwa and the gods of the place — with rice, with a fowl or a coconut, with the old words said by the old man who knows them — and asks plainly for what farmers everywhere ask: rain enough, and not too much, and the green to come up strong.","art":"art/story/sm/fk-hirwa-green.jpg","route":"#/story/fk.hirwa-green|s3","cta":"Read from here","why":"A moment from Hirwa of the Green","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.hirwa-green-5":{"src":"story:fk.hirwa-green:scenes:5:text","title":"Hirwa of the Green · 6 of 8","body":"Grass on the bunds. Leaves on the dusty trees. Rice seedlings in the flooded fields like green flame. Frogs shouting all night as if they had invented water. The whole territory, one of the smallest in India, becomes one of the greenest places you will ever see.","art":"art/story/sm/fk-hirwa-green.jpg","route":"#/story/fk.hirwa-green|s5","cta":"Read from here","why":"A moment from Hirwa of the Green","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.hirwa-green-6":{"src":"story:fk.hirwa-green:scenes:6:text","title":"Hirwa of the Green · 7 of 8","body":"And in the Warli paintings on the mud walls, the god of all this is there among the others — because a people who live by the rain and the seed know exactly which god they cannot do without.","art":"art/story/sm/fk-hirwa-green.jpg","route":"#/story/fk.hirwa-green|s6","cta":"Read from here","why":"A moment from Hirwa of the Green","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-hokka-1":{"src":"story:fk.diu-hokka:scenes:1:text","title":"The Trees That Crossed the Sea · 2 of 8","body":"Here is the strange part. This tree is a baobab — and the baobab's family home is Africa, an ocean away. Its cousins stand on the African plains where elephants scratch against them. There are only a handful in all of India. And Diu, this one small island, has a whole scatter of them.","art":"art/story/sm/fk-diu-hokka.jpg","route":"#/story/fk.diu-hokka|s1","cta":"Read from here","why":"A moment from The Trees That Crossed the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-hokka-2":{"src":"story:fk.diu-hokka:scenes:2:text","title":"The Trees That Crossed the Sea · 3 of 8","body":"So every child in Diu eventually asks the excellent question: trees cannot swim, and they certainly cannot buy a boat ticket. How did the hokka get here?","art":"art/story/sm/fk-diu-hokka.jpg","route":"#/story/fk.diu-hokka|s2","cta":"Read from here","why":"A moment from The Trees That Crossed the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-hokka-3":{"src":"story:fk.diu-hokka:scenes:3:text","title":"The Trees That Crossed the Sea · 4 of 8","body":"For many hundreds of years, ships have gone back and forth between India's west coast and the coast of Africa — trading cloth, dates, timber, everything. In the years when Diu was a great port, and later a Portuguese one, sailors from many coasts walked its lanes. Somebody, sometime, planted a seed from home.","art":"art/story/sm/fk-diu-hokka.jpg","route":"#/story/fk.diu-hokka|s3","cta":"Read from here","why":"A moment from The Trees That Crossed the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-hokka-5":{"src":"story:fk.diu-hokka:scenes:5:text","title":"The Trees That Crossed the Sea · 6 of 8","body":"So the hokka trees of Diu are living harbour records. Every one of them says: ships came here from far away, and people came with the ships, and some of what they carried put down roots. You can read it without opening a single book — just stand under the tree and look up.","art":"art/story/sm/fk-diu-hokka.jpg","route":"#/story/fk.diu-hokka|s5","cta":"Read from here","why":"A moment from The Trees That Crossed the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-hokka-6":{"src":"story:fk.diu-hokka:scenes:6:text","title":"The Trees That Crossed the Sea · 7 of 8","body":"The people of Diu use the fruit, rest in the shade, and point the trees out to visitors with a certain owner's pride. The tree that crossed the sea is a Diu-wallah now, generations deep — which is, when you think about it, the story of every port town in the world.","art":"art/story/sm/fk-diu-hokka.jpg","route":"#/story/fk.diu-hokka|s6","cta":"Read from here","why":"A moment from The Trees That Crossed the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.daman-lighthouse-1":{"src":"story:fk.daman-lighthouse:scenes:1:text","title":"The Keeper of the Small Light · 2 of 8","body":"He was an old man, and the stair was steep, and he climbed it every single evening of his life — up into the lamp room, trim the wick, polish the glass, light the flame. Then he would look out at the darkening sea and say, in the way of the town, \"Boa noite\" — good night, in Portuguese — to every boat still out.","art":"art/story/sm/fk-daman-lighthouse.jpg","route":"#/story/fk.daman-lighthouse|s1","cta":"Read from here","why":"A moment from The Keeper of the Small Light","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.daman-lighthouse-2":{"src":"story:fk.daman-lighthouse:scenes:2:text","title":"The Keeper of the Small Light · 3 of 8","body":"His grandson climbed with him sometimes, counting the steps and complaining about most of them. \"It is such a small lamp,\" the boy said one evening. \"The sea is so big. What difference can it make?\"","art":"art/story/sm/fk-daman-lighthouse.jpg","route":"#/story/fk.daman-lighthouse|s2","cta":"Read from here","why":"A moment from The Keeper of the Small Light","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.daman-lighthouse-3":{"src":"story:fk.daman-lighthouse:scenes:3:text","title":"The Keeper of the Small Light · 4 of 8","body":"The keeper hung the lamp and watched it steady. \"The sea does not need a big light,\" he said. \"It needs a light that is always there. Ask any fisherman which he would rather have — a bonfire sometimes, or a candle every night, always in the same place.\"","art":"art/story/sm/fk-daman-lighthouse.jpg","route":"#/story/fk.daman-lighthouse|s3","cta":"Read from here","why":"A moment from The Keeper of the Small Light","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.daman-lighthouse-5":{"src":"story:fk.daman-lighthouse:scenes:5:text","title":"The Keeper of the Small Light · 6 of 8","body":"And out on the black water, boat by boat, the fishermen of Daman found the one steady point in a whole world of moving dark, and lined their bows on it, and came in past the fort wall into the calm of the river — soaked, bailing, and alive.","art":"art/story/sm/fk-daman-lighthouse.jpg","route":"#/story/fk.daman-lighthouse|s5","cta":"Read from here","why":"A moment from The Keeper of the Small Light","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.daman-lighthouse-6":{"src":"story:fk.daman-lighthouse:scenes:6:text","title":"The Keeper of the Small Light · 7 of 8","body":"Nobody cheered the keeper. Hardly anyone knew to. He put out the lamp at dawn as always, said \"Bom dia\" — good morning — to the harbour, and went down the long stair to his tea. The boats were in. The light had done its work. That was the whole of it.","art":"art/story/sm/fk-daman-lighthouse.jpg","route":"#/story/fk.daman-lighthouse|s6","cta":"Read from here","why":"A moment from The Keeper of the Small Light","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.nagoa-shankh-1":{"src":"story:fk.nagoa-shankh:scenes:1:text","title":"The Shell That Called the Boats · 2 of 8","body":"A boy found one after a storm, half buried at the tideline, and carried it home with both arms. His grandfather turned it over once and nodded. \"That is not a toy,\" he said. \"That is a voice. Bring it here and I will show you.\"","art":"art/story/sm/fk-nagoa-shankh.jpg","route":"#/story/fk.nagoa-shankh|s1","cta":"Read from here","why":"A moment from The Shell That Called the Boats","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.nagoa-shankh-2":{"src":"story:fk.nagoa-shankh:scenes:2:text","title":"The Shell That Called the Boats · 3 of 8","body":"The old man put the shell to his lips and blew — and out of it came a sound the boy felt in his chest before he heard it in his ears. Deep, round, enormous. It rolled out over the bay the way thunder rolls, and every head on the beach came up at once.","art":"art/story/sm/fk-nagoa-shankh.jpg","route":"#/story/fk.nagoa-shankh|s2","cta":"Read from here","why":"A moment from The Shell That Called the Boats","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.nagoa-shankh-3":{"src":"story:fk.nagoa-shankh:scenes:3:text","title":"The Shell That Called the Boats · 4 of 8","body":"\"When I was young, this was the beach's voice,\" said his grandfather. \"One long blast: come in, weather is turning. Two: all safe, all counted. A shell can be heard past the reef when a shout dies at the surf line. The sea taught us that trick, and gave us the instrument too.\"","art":"art/story/sm/fk-nagoa-shankh.jpg","route":"#/story/fk.nagoa-shankh|s3","cta":"Read from here","why":"A moment from The Shell That Called the Boats","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.nagoa-shankh-5":{"src":"story:fk.nagoa-shankh:scenes:5:text","title":"The Shell That Called the Boats · 6 of 8","body":"The boats heard it past the reef, and turned, and came in through the chop with the first squall chasing them, and the last one crossed into the calm as the rain arrived like a wall. Two short blasts then, though nobody could hear them in the downpour: all safe. All counted.","art":"art/story/sm/fk-nagoa-shankh.jpg","route":"#/story/fk.nagoa-shankh|s5","cta":"Read from here","why":"A moment from The Shell That Called the Boats","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.nagoa-shankh-6":{"src":"story:fk.nagoa-shankh:scenes:6:text","title":"The Shell That Called the Boats · 7 of 8","body":"The boy kept that shankh all his life, on a shelf where the salt air could reach it, and blew it on festival days when it was a temple sound and a happy one. But he kept it polished the way you keep a working tool, because he knew what else it was.","art":"art/story/sm/fk-nagoa-shankh.jpg","route":"#/story/fk.nagoa-shankh|s6","cta":"Read from here","why":"A moment from The Shell That Called the Boats","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-fort-cat-1":{"src":"story:fk.diu-fort-cat:scenes:1:text","title":"The Cat of the Sea Fort · 2 of 8","body":"There has always been a fort cat — that is the story the caretakers tell. In the old days the fort kept storerooms of grain and gunpowder, and where there is stored grain there are rats, and where there are rats, a cat is not a pet. A cat is staff.","art":"art/story/sm/fk-diu-fort-cat.jpg","route":"#/story/fk.diu-fort-cat|s1","cta":"Read from here","why":"A moment from The Cat of the Sea Fort","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-fort-cat-2":{"src":"story:fk.diu-fort-cat:scenes:2:text","title":"The Cat of the Sea Fort · 3 of 8","body":"The soldiers of long ago fed the first fort cat from their own rations, the tale goes, because she was worth ten of them at her particular job. No rat chewed the sacks on her watch. She patrolled the walls at night like a small striped sergeant, and everything squeaky kept its distance.","art":"art/story/sm/fk-diu-fort-cat.jpg","route":"#/story/fk.diu-fort-cat|s2","cta":"Read from here","why":"A moment from The Cat of the Sea Fort","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-fort-cat-3":{"src":"story:fk.diu-fort-cat:scenes:3:text","title":"The Cat of the Sea Fort · 4 of 8","body":"The soldiers are centuries gone. The grain stores are empty rooms where swallows nest. But go to the fort today and, likely as not, a cat is there — asleep on a cannon the sun has warmed, one ear turning to follow you like a radar.","art":"art/story/sm/fk-diu-fort-cat.jpg","route":"#/story/fk.diu-fort-cat|s3","cta":"Read from here","why":"A moment from The Cat of the Sea Fort","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-fort-cat-5":{"src":"story:fk.diu-fort-cat:scenes:5:text","title":"The Cat of the Sea Fort · 6 of 8","body":"Children who visit always find her, or she finds them — materialising beside a picnic with the timing of a customs officer. Feed her something and she accepts it graciously, as rent long owed. This is, after all, her fort. Records of any other owner are disputed.","art":"art/story/sm/fk-diu-fort-cat.jpg","route":"#/story/fk.diu-fort-cat|s5","cta":"Read from here","why":"A moment from The Cat of the Sea Fort","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.diu-fort-cat-6":{"src":"story:fk.diu-fort-cat:scenes:6:text","title":"The Cat of the Sea Fort · 7 of 8","body":"And at closing time, when the last visitor crosses back over the old moat and the gate is shut, the fort returns to its true garrison: the swallows, the sea wind in the embrasures, and one cat on the wall, on watch, as the light goes gold.","art":"art/story/sm/fk-diu-fort-cat.jpg","route":"#/story/fk.diu-fort-cat|s6","cta":"Read from here","why":"A moment from The Cat of the Sea Fort","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.gangeshwar-tide-1":{"src":"story:fk.gangeshwar-tide:scenes:1:text","title":"The Shrine the Sea Visits · 2 of 8","body":"This is how the katha is told in Diu. Long ago, in their years of wandering, the five Pandava brothers came along this shore. They wished to worship Shiva, and there was no temple — so each brother set a shivling in the living rock, five together, at the edge of the sea.","art":"art/story/sm/fk-gangeshwar-tide.jpg","route":"#/story/fk.gangeshwar-tide|s1","cta":"Read from here","why":"A moment from The Shrine the Sea Visits","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.gangeshwar-tide-2":{"src":"story:fk.gangeshwar-tide:scenes:2:text","title":"The Shrine the Sea Visits · 3 of 8","body":"They chose the spot, the telling goes, with open eyes. Not safely up the beach. Down at the tideline, where the sea could reach. And when the tide came in and the first wave washed over the five lings, the brothers saw that it was exactly right, and went on their way content.","art":"art/story/sm/fk-gangeshwar-tide.jpg","route":"#/story/fk.gangeshwar-tide|s2","cta":"Read from here","why":"A moment from The Shrine the Sea Visits","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.gangeshwar-tide-3":{"src":"story:fk.gangeshwar-tide:scenes:3:text","title":"The Shrine the Sea Visits · 4 of 8","body":"Because twice every day, without fail, the sea rises and comes hushing in over the rocks, and pours itself over the five shivlings, and drains away again — leaving them washed, gleaming, and garlanded with foam.","art":"art/story/sm/fk-gangeshwar-tide.jpg","route":"#/story/fk.gangeshwar-tide|s3","cta":"Read from here","why":"A moment from The Shrine the Sea Visits","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.gangeshwar-tide-5":{"src":"story:fk.gangeshwar-tide:scenes:5:text","title":"The Shrine the Sea Visits · 6 of 8","body":"People leave flowers on the wet rock, and the next wave gathers them up and carries them out — which, at this shrine, does not feel like the offering being lost. It feels like the offering being accepted.","art":"art/story/sm/fk-gangeshwar-tide.jpg","route":"#/story/fk.gangeshwar-tide|s5","cta":"Read from here","why":"A moment from The Shrine the Sea Visits","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.gangeshwar-tide-6":{"src":"story:fk.gangeshwar-tide:scenes:6:text","title":"The Shrine the Sea Visits · 7 of 8","body":"Ganga, they say, lives in Shiva's hair — the great river caught in his locks as she fell from heaven. At Gangeshwar it is as if the story turned itself around, just here: the water comes to him, twice a day, respectful as a river bowing.","art":"art/story/sm/fk-gangeshwar-tide.jpg","route":"#/story/fk.gangeshwar-tide|s6","cta":"Read from here","why":"A moment from The Shrine the Sea Visits","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.koli-stars-1":{"src":"story:fk.koli-stars:scenes:1:text","title":"The Fisherman's Compass · 2 of 8","body":"The girl had saved up for it at the market: brass, with a needle that swung like magic and a lid that clicked. She brought it aboard her grandfather's boat with enormous pride. Her grandfather admired it properly, the way grandfathers do, and put it carefully on the thwart.","art":"art/story/sm/fk-koli-stars.jpg","route":"#/story/fk.koli-stars|s1","cta":"Read from here","why":"A moment from The Fisherman's Compass","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.koli-stars-2":{"src":"story:fk.koli-stars:scenes:2:text","title":"The Fisherman's Compass · 3 of 8","body":"\"Now you can never be lost, dada,\" she said. Her grandfather looked at the sea and made the small sound old fishermen make, which can mean anything. \"I have not been lost in sixty years,\" he said. \"But it is a fine compass.\"","art":"art/story/sm/fk-koli-stars.jpg","route":"#/story/fk.koli-stars|s2","cta":"Read from here","why":"A moment from The Fisherman's Compass","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.koli-stars-3":{"src":"story:fk.koli-stars:scenes:3:text","title":"The Fisherman's Compass · 4 of 8","body":"They were far out, past sight of the flat Daman shore, when a swell knocked the thwart and the compass went over the side — one gleam, and gone. The girl burst into tears. All her savings, and worse: now, she was sure, they were lost.","art":"art/story/sm/fk-koli-stars.jpg","route":"#/story/fk.koli-stars|s3","cta":"Read from here","why":"A moment from The Fisherman's Compass","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.koli-stars-5":{"src":"story:fk.koli-stars:scenes:5:text","title":"The Fisherman's Compass · 6 of 8","body":"All the way in he showed her: how the swell bends as the water shallows, how the wind smells different off the land in the evening, how the first star hangs where it hung for his grandfather. The sky came out like a chart pricked in silver, and he named the stars fishermen steer by.","art":"art/story/sm/fk-koli-stars.jpg","route":"#/story/fk.koli-stars|s5","cta":"Read from here","why":"A moment from The Fisherman's Compass","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.koli-stars-6":{"src":"story:fk.koli-stars:scenes:6:text","title":"The Fisherman's Compass · 7 of 8","body":"They raised the lights of Daman exactly where he said they would be. \"The shop compass is good,\" he said, tying up. \"Buy another. But keep this one too\" — he tapped her forehead — \"wound up and working. Instruments fall in the sea. What you know floats.\"","art":"art/story/sm/fk-koli-stars.jpg","route":"#/story/fk.koli-stars|s6","cta":"Read from here","why":"A moment from The Fisherman's Compass","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.narali-punam-1":{"src":"story:fk.narali-punam:scenes:1:text","title":"The Coconut for the Sea · 2 of 8","body":"It comes at the monsoon's end: Narali Purnima, the coconut full moon. On that day, all along the western coast, fishing communities go down to the water dressed in their best, singing, carrying coconuts — and give them to the sea.","art":"art/story/sm/fk-narali-punam.jpg","route":"#/story/fk.narali-punam|s1","cta":"Read from here","why":"A moment from The Coconut for the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.narali-punam-2":{"src":"story:fk.narali-punam:scenes:2:text","title":"The Coconut for the Sea · 3 of 8","body":"In Daman the boats are decorated like relatives at a wedding — fresh paint, flags, flowers on the prow. Families walk down together, the coconuts are offered into the waves with prayers, and the water rocks them away, bright against the grey-green swell.","art":"art/story/sm/fk-narali-punam.jpg","route":"#/story/fk.narali-punam|s2","cta":"Read from here","why":"A moment from The Coconut for the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.narali-punam-3":{"src":"story:fk.narali-punam:scenes:3:text","title":"The Coconut for the Sea · 4 of 8","body":"A boy watching for the first time asked his mother the obvious, excellent question. \"The sea is full of everything already. Why are we giving it a coconut?\"","art":"art/story/sm/fk-narali-punam.jpg","route":"#/story/fk.narali-punam|s3","cta":"Read from here","why":"A moment from The Coconut for the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.narali-punam-5":{"src":"story:fk.narali-punam:scenes:5:text","title":"The Coconut for the Sea · 6 of 8","body":"And with the offering made, the season opens. Within days the harbour empties at dawn, the boats spreading out over water that has, in everyone's eyes, been properly spoken to. The old agreement, renewed for another year.","art":"art/story/sm/fk-narali-punam.jpg","route":"#/story/fk.narali-punam|s5","cta":"Read from here","why":"A moment from The Coconut for the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.narali-punam-6":{"src":"story:fk.narali-punam:scenes:6:text","title":"The Coconut for the Sea · 7 of 8","body":"Up and down the coast — in Maharashtra, in Gujarat, here in Daman — fishing communities keep this day, each in their own way, with their own songs. In many families the coconut is broken and shared afterwards too; ask a coastal family how theirs does it.","art":"art/story/sm/fk-narali-punam.jpg","route":"#/story/fk.narali-punam|s6","cta":"Read from here","why":"A moment from The Coconut for the Sea","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.moti-daman-bells-1":{"src":"story:fk.moti-daman-bells:scenes:1:text","title":"The Bell That Answered Ships · 2 of 8","body":"This is a tale of that bell, from the days when Daman was a Portuguese port and the river below the fort was busy with sails. It is told the way harbour tales are told — leaning on a wall, watching the water.","art":"art/story/sm/fk-moti-daman-bells.jpg","route":"#/story/fk.moti-daman-bells|s1","cta":"Read from here","why":"A moment from The Bell That Answered Ships","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.moti-daman-bells-2":{"src":"story:fk.moti-daman-bells:scenes:2:text","title":"The Bell That Answered Ships · 3 of 8","body":"Every evening at dusk the bell rang across the river, and every vessel coming up from the sea heard it. To a crew that had been out for days, wet and tired, that sound reaching them over the water meant one thing before it meant anything churchly: Daman. We are home.","art":"art/story/sm/fk-moti-daman-bells.jpg","route":"#/story/fk.moti-daman-bells|s2","cta":"Read from here","why":"A moment from The Bell That Answered Ships","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.moti-daman-bells-3":{"src":"story:fk.moti-daman-bells:scenes:3:text","title":"The Bell That Answered Ships · 4 of 8","body":"The old bell-ringer, the tale goes, understood this perfectly. A priest once found him ringing on a foul black evening, long past the usual hour, hauling away in the wind. \"The hour is gone,\" said the priest. \"For whom are you ringing?\"","art":"art/story/sm/fk-moti-daman-bells.jpg","route":"#/story/fk.moti-daman-bells|s3","cta":"Read from here","why":"A moment from The Bell That Answered Ships","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.moti-daman-bells-5":{"src":"story:fk.moti-daman-bells:scenes:5:text","title":"The Bell That Answered Ships · 6 of 8","body":"Here is the lovely thing about a Daman evening, then and now. The church bell is not the only voice. Across the town, as the light goes, the azaan rises from the mosque, and the aarti bells sound from the temples — different prayers, in different houses of God, floating out over the same river.","art":"art/story/sm/fk-moti-daman-bells.jpg","route":"#/story/fk.moti-daman-bells|s5","cta":"Read from here","why":"A moment from The Bell That Answered Ships","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.moti-daman-bells-6":{"src":"story:fk.moti-daman-bells:scenes:6:text","title":"The Bell That Answered Ships · 7 of 8","body":"And every one of those sounds, whatever else it carries, carries the bell-ringer's message too. Day is ending. You are not alone. Come home. Sailors of every faith steered by whichever voice reached them, and were glad of them all.","art":"art/story/sm/fk-moti-daman-bells.jpg","route":"#/story/fk.moti-daman-bells|s6","cta":"Read from here","why":"A moment from The Bell That Answered Ships","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-two-bells-1":{"src":"story:fk.goa-two-bells:scenes:1:text","title":"The Two Bells of the Valley · 2 of 8","body":"Each hill had its bell. The church bell was big and bronze and rang for Mass and the Angelus. The temple bell was smaller and brighter and rang for the morning and evening aarti. And between them, in the valley, everybody's rice grew in everybody's sight.","art":"art/story/sm/fk-goa-two-bells.jpg","route":"#/story/fk.goa-two-bells|s1","cta":"Read from here","why":"A moment from The Two Bells of the Valley","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-two-bells-2":{"src":"story:fk.goa-two-bells:scenes:2:text","title":"The Two Bells of the Valley · 3 of 8","body":"The two bell-ringers had never planned anything. But bells carry in a valley, and slowly, over years, a politeness grew. If the temple bell was sounding, the church ringer waited for the pause before he began. If the church bell was mid-peal, the temple ringer let it finish. Neither would ring over the other.","art":"art/story/sm/fk-goa-two-bells.jpg","route":"#/story/fk.goa-two-bells|s2","cta":"Read from here","why":"A moment from The Two Bells of the Valley","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-two-bells-3":{"src":"story:fk.goa-two-bells:scenes:3:text","title":"The Two Bells of the Valley · 4 of 8","body":"A child once asked her grandmother about it — a Catholic grandmother, as it happens, shelling peas on her balcao. \"Aji, why does our bell wait for theirs?\"","art":"art/story/sm/fk-goa-two-bells.jpg","route":"#/story/fk.goa-two-bells|s3","cta":"Read from here","why":"A moment from The Two Bells of the Valley","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-two-bells-5":{"src":"story:fk.goa-two-bells:scenes:5:text","title":"The Two Bells of the Valley · 6 of 8","body":"People from away sometimes asked the villagers how the two hills got along so well, as if it were a wonder. The villagers found the question odd. \"We have always been here,\" they would say, \"both of us. The valley is one valley. The rice does not grow in two colours.\"","art":"art/story/sm/fk-goa-two-bells.jpg","route":"#/story/fk.goa-two-bells|s5","cta":"Read from here","why":"A moment from The Two Bells of the Valley","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-two-bells-6":{"src":"story:fk.goa-two-bells:scenes:6:text","title":"The Two Bells of the Valley · 7 of 8","body":"In the evenings, when both bells had rung and the frogs were starting up in the paddies, you could stand on the bund between the hills and feel it: two houses of God, lit against the dusk, each keeping its own prayers and keeping, also, an ear for the other.","art":"art/story/sm/fk-goa-two-bells.jpg","route":"#/story/fk.goa-two-bells|s6","cta":"Read from here","why":"A moment from The Two Bells of the Valley","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-coconut-1":{"src":"story:fk.goa-coconut:scenes:1:text","title":"The Tree That Held the Village · 2 of 8","body":"The rains came that year like an upturned sea. The river left its bed, walked through the fields, and sat on the rice until the rice was gone. When the water finally drew back, the village stood looking at grey mud where a year of food should have been.","art":"art/story/sm/fk-goa-coconut.jpg","route":"#/story/fk.goa-coconut|s1","cta":"Read from here","why":"A moment from The Tree That Held the Village","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-coconut-2":{"src":"story:fk.goa-coconut:scenes:2:text","title":"The Tree That Held the Village · 3 of 8","body":"But standing out of the mud, untroubled, leaning the way they always leaned — the coconut palms. The flood had swirled round their trunks for a week and they had simply held on. Palms know water. They grow with their feet nearly in the sea all their lives.","art":"art/story/sm/fk-goa-coconut.jpg","route":"#/story/fk.goa-coconut|s2","cta":"Read from here","why":"A moment from The Tree That Held the Village","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-coconut-3":{"src":"story:fk.goa-coconut:scenes:3:text","title":"The Tree That Held the Village · 4 of 8","body":"The village headwoman gathered everyone. \"The rice is gone and the next harvest is months away,\" she said. \"Now — before anyone despairs — somebody count for me what we still have.\" And she pointed up at the palms.","art":"art/story/sm/fk-goa-coconut.jpg","route":"#/story/fk.goa-coconut|s3","cta":"Read from here","why":"A moment from The Tree That Held the Village","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-coconut-5":{"src":"story:fk.goa-coconut:scenes:5:text","title":"The Tree That Held the Village · 6 of 8","body":"When the new rice finally stood green in the mended fields, the headwoman called the village together once more — under the palms this time — and made the announcement the tale is really told for: \"From this year, no one in this village cuts a healthy maad. I do not care whose land it stands on. These trees are the village's grandmothers.\"","art":"art/story/sm/fk-goa-coconut.jpg","route":"#/story/fk.goa-coconut|s5","cta":"Read from here","why":"A moment from The Tree That Held the Village","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-coconut-6":{"src":"story:fk.goa-coconut:scenes:6:text","title":"The Tree That Held the Village · 7 of 8","body":"Goans have called the coconut palm kalpavriksha — the wish-fulfilling tree of the old stories — for as long as anyone can say, and they mean it almost literally. Ask a Goan household how many things in the kitchen came from the maad. Then count the roof.","art":"art/story/sm/fk-goa-coconut.jpg","route":"#/story/fk.goa-coconut|s6","cta":"Read from here","why":"A moment from The Tree That Held the Village","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-frog-rain-1":{"src":"story:fk.goa-frog-rain:scenes:1:text","title":"The Frog Who Called the Rain · 2 of 8","body":"The rains were late. Terribly late. June was ending, the fields lay cracked like old pottery, and the frogs sat silent in the last damp hollows, saving themselves. What is the point of singing the rain in, they said, when there is no rain to sing to?","art":"art/story/sm/fk-goa-frog-rain.jpg","route":"#/story/fk.goa-frog-rain|s1","cta":"Read from here","why":"A moment from The Frog Who Called the Rain","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-frog-rain-2":{"src":"story:fk.goa-frog-rain:scenes:2:text","title":"The Frog Who Called the Rain · 3 of 8","body":"All but one. The smallest frog in the lowest paddy — a frog the size of a thumbnail, with a voice to match — climbed onto a clod every evening and sang anyway. Tink. Tink. Tink. Alone, into a dry sky the colour of brass.","art":"art/story/sm/fk-goa-frog-rain.jpg","route":"#/story/fk.goa-frog-rain|s2","cta":"Read from here","why":"A moment from The Frog Who Called the Rain","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-frog-rain-3":{"src":"story:fk.goa-frog-rain:scenes:3:text","title":"The Frog Who Called the Rain · 4 of 8","body":"A crow heckled him from the bund, because crows will. \"Save your breath, little one. The big frogs have stopped. The sky is not listening.\" The little frog finished his verse first, politely, and then answered: \"The sky is exactly who I am singing to. Somebody has to keep the invitation open.\"","art":"art/story/sm/fk-goa-frog-rain.jpg","route":"#/story/fk.goa-frog-rain|s3","cta":"Read from here","why":"A moment from The Frog Who Called the Rain","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-frog-rain-5":{"src":"story:fk.goa-frog-rain:scenes:5:text","title":"The Frog Who Called the Rain · 6 of 8","body":"And that night — the tale insists on this part — the wind swung round to the sea, and a smell of wet earth came up the valley, and the first fat drops fell hissing on the dust. By morning the whole sky had opened, and every frog in Goa was singing at the absolute top of its voice.","art":"art/story/sm/fk-goa-frog-rain.jpg","route":"#/story/fk.goa-frog-rain|s5","cta":"Read from here","why":"A moment from The Frog Who Called the Rain","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-frog-rain-6":{"src":"story:fk.goa-frog-rain:scenes:6:text","title":"The Frog Who Called the Rain · 7 of 8","body":"The paddies filled. The rice went in. And the big frogs, it is said, were too glad to be embarrassed — though the crow made sure they heard about it, at length, from the bund.","art":"art/story/sm/fk-goa-frog-rain.jpg","route":"#/story/fk.goa-frog-rain|s6","cta":"Read from here","why":"A moment from The Frog Who Called the Rain","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-shigmo-1":{"src":"story:fk.goa-shigmo:scenes:1:text","title":"When Spring Beats the Drum · 2 of 8","body":"It begins in the villages. Bands of dancers — the romta mell — go from house to house and temple to temple with flags the colour of flame, with dhol and tasha drums, with cymbals and flutes, dancing in the lanes they have danced in for centuries.","art":"art/story/sm/fk-goa-shigmo.jpg","route":"#/story/fk.goa-shigmo|s1","cta":"Read from here","why":"A moment from When Spring Beats the Drum","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-shigmo-2":{"src":"story:fk.goa-shigmo:scenes:2:text","title":"When Spring Beats the Drum · 3 of 8","body":"The old tellings give Shigmo more than one beginning. In many villages it is told as the festival of homecoming — the season when, long ago, the men who had been away at war or on journeys came home to their families, and were met with drums, dancing and flowers in the streets.","art":"art/story/sm/fk-goa-shigmo.jpg","route":"#/story/fk.goa-shigmo|s2","cta":"Read from here","why":"A moment from When Spring Beats the Drum","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-shigmo-3":{"src":"story:fk.goa-shigmo:scenes:3:text","title":"When Spring Beats the Drum · 4 of 8","body":"A drummer teaching his daughter the rhythms put it this way: \"Winter is quiet and careful. The fields are cut, the nights are cool, everyone saves and waits. Then the flowers come. And what should a person do when the waiting ends?\"","art":"art/story/sm/fk-goa-shigmo.jpg","route":"#/story/fk.goa-shigmo|s3","cta":"Read from here","why":"A moment from When Spring Beats the Drum","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-shigmo-5":{"src":"story:fk.goa-shigmo:scenes:5:text","title":"When Spring Beats the Drum · 6 of 8","body":"And in the proper Goan way, the lanes fill with everybody. Catholic neighbours come out to watch the mell go past and know the drummers by name; visitors get colour on their faces and sweets in their hands. A Goan festival has never been good at staying inside one gate.","art":"art/story/sm/fk-goa-shigmo.jpg","route":"#/story/fk.goa-shigmo|s5","cta":"Read from here","why":"A moment from When Spring Beats the Drum","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-shigmo-6":{"src":"story:fk.goa-shigmo:scenes:6:text","title":"When Spring Beats the Drum · 7 of 8","body":"The drums pass down from shoulder to shoulder, father to daughter, uncle to nephew. A child in a Shigmo village learns the rhythms the way they learn to swim — by being in the middle of it every spring until, one year, the drum is on their own shoulder.","art":"art/story/sm/fk-goa-shigmo.jpg","route":"#/story/fk.goa-shigmo|s6","cta":"Read from here","why":"A moment from When Spring Beats the Drum","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.mandovi-mugger-1":{"src":"story:fk.mandovi-mugger:scenes:1:text","title":"The Crocodile Who Owns His Stretch · 2 of 8","body":"They have been there longer than anyone's records. The fisherfolk who work the channel know their haul-out banks the way you know which neighbour's scooter is whose, and give them room. The crocodiles, for their part, mostly mind their own considerable business.","art":"art/story/sm/fk-mandovi-mugger.jpg","route":"#/story/fk.mandovi-mugger|s1","cta":"Read from here","why":"A moment from The Crocodile Who Owns His Stretch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.mandovi-mugger-2":{"src":"story:fk.mandovi-mugger:scenes:2:text","title":"The Crocodile Who Owns His Stretch · 3 of 8","body":"And in villages by these waters, the farmers keep a custom that surprises everyone who hears of it. Once a year, after the harvest, they build a crocodile — life-sized, out of wet clay and shells — on the bund beside the water, and honour it with flowers and offerings.","art":"art/story/sm/fk-mandovi-mugger.jpg","route":"#/story/fk.mandovi-mugger|s2","cta":"Read from here","why":"A moment from The Crocodile Who Owns His Stretch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.mandovi-mugger-3":{"src":"story:fk.mandovi-mugger:scenes:3:text","title":"The Crocodile Who Owns His Stretch · 4 of 8","body":"The custom is called Mannge Thapnee — the setting-up of the crocodile. A visitor once asked an old farmer the obvious question: why honour the animal most people would rather wish away?","art":"art/story/sm/fk-mandovi-mugger.jpg","route":"#/story/fk.mandovi-mugger|s3","cta":"Read from here","why":"A moment from The Crocodile Who Owns His Stretch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.mandovi-mugger-5":{"src":"story:fk.mandovi-mugger:scenes:5:text","title":"The Crocodile Who Owns His Stretch · 6 of 8","body":"Meanwhile the scientists come with binoculars and notebooks, counting the muggers and studying how such big wild animals live so close to so many people. Their finding, in short: the sharing mostly works — and the old respect is a large part of why.","art":"art/story/sm/fk-mandovi-mugger.jpg","route":"#/story/fk.mandovi-mugger|s5","cta":"Read from here","why":"A moment from The Crocodile Who Owns His Stretch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.mandovi-mugger-6":{"src":"story:fk.mandovi-mugger:scenes:6:text","title":"The Crocodile Who Owns His Stretch · 7 of 8","body":"So on a quiet morning you can drift down the channel and see it all at once: mangroves, fishing canoes, a heron statue-still on a post, and on the far bank a three-metre mugger asleep in the sun — everyone keeping, more or less politely, to their own stretch.","art":"art/story/sm/fk-mandovi-mugger.jpg","route":"#/story/fk.mandovi-mugger|s6","cta":"Read from here","why":"A moment from The Crocodile Who Owns His Stretch","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-mando-1":{"src":"story:fk.goa-mando:scenes:1:text","title":"The Song That Keeps the Story · 2 of 8","body":"The singers stand together, and with them plays the ghumot — Goa's own clay-pot drum, warmed by a fire before playing so its voice comes right — and maybe a violin, which the Portuguese years left behind in Goan parlours the way the sea leaves shells.","art":"art/story/sm/fk-goa-mando.jpg","route":"#/story/fk.goa-mando|s1","cta":"Read from here","why":"A moment from The Song That Keeps the Story","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-mando-2":{"src":"story:fk.goa-mando:scenes:2:text","title":"The Song That Keeps the Story · 3 of 8","body":"Every mando tells something. Some are love stories, full of longing across a courtyard. Some remember real happenings from long ago — a wedding, a parting, even village quarrels and old injustices, all smoothed by melody into something a family can hold. The mando is how Goan Catholic families kept their diary: in verse, in Konkani, in four-part sweetness.","art":"art/story/sm/fk-goa-mando.jpg","route":"#/story/fk.goa-mando|s2","cta":"Read from here","why":"A moment from The Song That Keeps the Story","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-mando-3":{"src":"story:fk.goa-mando:scenes:3:text","title":"The Song That Keeps the Story · 4 of 8","body":"At one wedding, so the affectionate joke goes, a boy whispered to his grandmother: \"Why is everyone nearly crying? It is a happy day.\" His grandmother was singing the refrain and made him wait for the verse-end, which is the correct order of things.","art":"art/story/sm/fk-goa-mando.jpg","route":"#/story/fk.goa-mando|s3","cta":"Read from here","why":"A moment from The Song That Keeps the Story","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-mando-5":{"src":"story:fk.goa-mando:scenes:5:text","title":"The Song That Keeps the Story · 6 of 8","body":"New mandos were made for new happenings, decade after decade, so the songbook grew along with the families. Sing through a village's mandos in order and you have sung its history — told from the inside, in its own kitchen language.","art":"art/story/sm/fk-goa-mando.jpg","route":"#/story/fk.goa-mando|s5","cta":"Read from here","why":"A moment from The Song That Keeps the Story","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.goa-mando-6":{"src":"story:fk.goa-mando:scenes:6:text","title":"The Song That Keeps the Story · 7 of 8","body":"Today there are mando festivals and competitions, choirs that polish it like silver, recordings that carry it to Goan families in Lisbon and London and Toronto — who play them at their own weddings, and cry the same good tears in a colder climate.","art":"art/story/sm/fk-goa-mando.jpg","route":"#/story/fk.goa-mando|s6","cta":"Read from here","why":"A moment from The Song That Keeps the Story","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kharvi-wave-1":{"src":"story:fk.kharvi-wave:scenes:1:text","title":"The Sea Speaks in Sevens · 2 of 8","body":"Every morning, before the boats went out, old Pedru — everyone's grand-uncle, brown as a coir rope — walked to the water's edge and simply stood there. Watching. Counting under his breath. Only after a long while would he turn and say \"yes\" or \"no\", and the beach obeyed him like weather.","art":"art/story/sm/fk-kharvi-wave.jpg","route":"#/story/fk.kharvi-wave|s1","cta":"Read from here","why":"A moment from The Sea Speaks in Sevens","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kharvi-wave-2":{"src":"story:fk.kharvi-wave:scenes:2:text","title":"The Sea Speaks in Sevens · 3 of 8","body":"A boy finally asked him what he was counting. \"The waves,\" said Pedru. \"The sea does not send them all alike. She sends them in families — some small, then the big ones together. Stand still long enough and you learn the size of the family she is sending today, and the mood she sent it in.\"","art":"art/story/sm/fk-kharvi-wave.jpg","route":"#/story/fk.kharvi-wave|s2","cta":"Read from here","why":"A moment from The Sea Speaks in Sevens","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kharvi-wave-3":{"src":"story:fk.kharvi-wave:scenes:3:text","title":"The Sea Speaks in Sevens · 4 of 8","body":"He taught the boy the rest of the listening, too. The colour of the water out past the break. What it means when the wind and the swell disagree with each other. Why birds sitting on the water say one thing and birds flying high and silent say another.","art":"art/story/sm/fk-kharvi-wave.jpg","route":"#/story/fk.kharvi-wave|s3","cta":"Read from here","why":"A moment from The Sea Speaks in Sevens","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kharvi-wave-5":{"src":"story:fk.kharvi-wave:scenes:5:text","title":"The Sea Speaks in Sevens · 6 of 8","body":"The boy grew into the man who stood at the water's edge in his turn, counting, with a child beside him asking what he was doing. That is how the Kharvi kept their knowledge for all the centuries before barometers: one beach, one dawn, one patient explanation at a time.","art":"art/story/sm/fk-kharvi-wave.jpg","route":"#/story/fk.kharvi-wave|s5","cta":"Read from here","why":"A moment from The Sea Speaks in Sevens","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-fk.kharvi-wave-6":{"src":"story:fk.kharvi-wave:scenes:6:text","title":"The Sea Speaks in Sevens · 7 of 8","body":"The boats have engines now, and the phone knows the forecast. But watch an old Goan fisherman on the sand some morning. He will still be reading the water with his eyes before he trusts the screen — checking the sea's own signature against the letter.","art":"art/story/sm/fk-kharvi-wave.jpg","route":"#/story/fk.kharvi-wave|s6","cta":"Read from here","why":"A moment from The Sea Speaks in Sevens","facts":[["From","The Coast and the Forest"],["Read","4 min"]]},"ss-it.jijabai-stories-1":{"src":"story:it.jijabai-stories:scenes:1:text","title":"The Stories His Mother Told · 2 of 8","body":"His father Shahaji served far away in the south for much of those years, so it was Jijabai who raised the boy — first at Shivneri, later at Pune, where she and young Shivaji settled and made a half-ruined place into a home and a beginning.","art":"art/story/sm/it-jijabai-stories.jpg","route":"#/story/it.jijabai-stories|s1","cta":"Read from here","why":"A moment from The Stories His Mother Told","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-it.jijabai-stories-2":{"src":"story:it.jijabai-stories:scenes:2:text","title":"The Stories His Mother Told · 3 of 8","body":"And this is what the Maratha tradition remembers best about that upbringing, told over and over down the generations: Jijabai gave her son the epics. Evenings of the Ramayana. The Mahabharata, told the way a strong-minded mother tells it — dwelling on the just kings, the keeping of word, the refusal to bow to what is wrong.","art":"art/story/sm/it-jijabai-stories.jpg","route":"#/story/it.jijabai-stories|s2","cta":"Read from here","why":"A moment from The Stories His Mother Told","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-it.jijabai-stories-3":{"src":"story:it.jijabai-stories:scenes:3:text","title":"The Stories His Mother Told · 4 of 8","body":"Picture the boy listening. Around him, in plain sight, the world the stories judged: forts on every hilltop, armies passing, ordinary farmers bearing the weight of it all. The old bakhars — the Marathi chronicles — say the mother's telling and the mother's own fierce piety shaped everything the boy became.","art":"art/story/sm/it-jijabai-stories.jpg","route":"#/story/it.jijabai-stories|s3","cta":"Read from here","why":"A moment from The Stories His Mother Told","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-it.jijabai-stories-5":{"src":"story:it.jijabai-stories:scenes:5:text","title":"The Stories His Mother Told · 6 of 8","body":"What did it grow into? A man who, by the plain record, built forts and a navy, ran an administration in Marathi, was crowned at Raigad — and whom the ballads of Maharashtra have sung for three and a half centuries as the king the old stories would have approved of.","art":"art/story/sm/it-jijabai-stories.jpg","route":"#/story/it.jijabai-stories|s5","cta":"Read from here","why":"A moment from The Stories His Mother Told","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-it.jijabai-stories-6":{"src":"story:it.jijabai-stories:scenes:6:text","title":"The Stories His Mother Told · 7 of 8","body":"And Jijabai lived to see it. She lived until just after the coronation at Raigad — as if, the tradition likes to say, she stayed exactly long enough to see the story she had been telling come true.","art":"art/story/sm/it-jijabai-stories.jpg","route":"#/story/it.jijabai-stories|s6","cta":"Read from here","why":"A moment from The Stories His Mother Told","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.warkari-ant-1":{"src":"story:fk.warkari-ant:scenes:1:text","title":"The Ant on the Palkhi Road · 2 of 8","body":"This is a story the Warkari tellers like to tell about that road. One year, at the very tail of the great procession, a walker looked down and saw an ant — one small black ant, walking in the dust, heading the same way as everybody else.","art":"art/story/sm/fk-warkari-ant.jpg","route":"#/story/fk.warkari-ant|s1","cta":"Read from here","why":"A moment from The Ant on the Palkhi Road","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.warkari-ant-2":{"src":"story:fk.warkari-ant:scenes:2:text","title":"The Ant on the Palkhi Road · 3 of 8","body":"\"And where are you going, little one?\" he asked, mostly joking. \"To Pandharpur,\" said the ant, not stopping, \"to see Vitthal.\" The walker laughed before he could help it. \"Mavshi, it is many days' walking for me. For you it is the journey of ten lifetimes. You will never reach.\"","art":"art/story/sm/fk-warkari-ant.jpg","route":"#/story/fk.warkari-ant|s2","cta":"Read from here","why":"A moment from The Ant on the Palkhi Road","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.warkari-ant-3":{"src":"story:fk.warkari-ant:scenes:3:text","title":"The Ant on the Palkhi Road · 4 of 8","body":"The ant kept walking. \"Then I will reach in ten lifetimes,\" she said. \"You are walking because you love him. I am walking because I love him. In what way is your walking bigger than mine?\"","art":"art/story/sm/fk-warkari-ant.jpg","route":"#/story/fk.warkari-ant|s3","cta":"Read from here","why":"A moment from The Ant on the Palkhi Road","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.warkari-ant-5":{"src":"story:fk.warkari-ant:scenes:5:text","title":"The Ant on the Palkhi Road · 6 of 8","body":"That is the part the tellers lean on. On the Warkari road, every walker calls every other walker \"Mauli\" — mother — whether they are a professor or a farmer or, apparently, an ant. Whoever tires is carried along by the rest. The procession is one body with a lakh of feet.","art":"art/story/sm/fk-warkari-ant.jpg","route":"#/story/fk.warkari-ant|s5","cta":"Read from here","why":"A moment from The Ant on the Palkhi Road","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.warkari-ant-6":{"src":"story:fk.warkari-ant:scenes:6:text","title":"The Ant on the Palkhi Road · 7 of 8","body":"Did the ant reach Pandharpur? In the telling, she rode into town on a singing shoulder, and saw Vitthal from the best seat on the road. Ten lifetimes' journey, done in one — not because her legs grew longer, but because the road itself picked her up.","art":"art/story/sm/fk-warkari-ant.jpg","route":"#/story/fk.warkari-ant|s6","cta":"Read from here","why":"A moment from The Ant on the Palkhi Road","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.tukaram-notebooks-1":{"src":"story:fk.tukaram-notebooks:scenes:1:text","title":"The Notebooks That Came Back · 2 of 8","body":"That plainness was the wonder of them, and the trouble. A farmer could sing them at the plough. A grandmother could hold one like a lamp. But some learned men of the day were scandalised: sacred things, they said, belonged in Sanskrit, in the proper hands. Who was this villager, pouring God out in everyday words?","art":"art/story/sm/fk-tukaram-notebooks.jpg","route":"#/story/fk.tukaram-notebooks|s1","cta":"Read from here","why":"A moment from The Notebooks That Came Back","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.tukaram-notebooks-2":{"src":"story:fk.tukaram-notebooks:scenes:2:text","title":"The Notebooks That Came Back · 3 of 8","body":"The pressure ended in a cruel demand. The notebooks — the vahis in which Tukaram's life of poems was written — were to be sunk in the Indrayani. And, the katha says, sunk they were: weighted, and given to the river, while Tukaram watched.","art":"art/story/sm/fk-tukaram-notebooks.jpg","route":"#/story/fk.tukaram-notebooks|s2","cta":"Read from here","why":"A moment from The Notebooks That Came Back","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.tukaram-notebooks-3":{"src":"story:fk.tukaram-notebooks:scenes:3:text","title":"The Notebooks That Came Back · 4 of 8","body":"What does a poet do when his life's work goes under the water? Tukaram did not shout, and he did not go home. He sat down on the bank of the Indrayani and turned to the one he had written every line for. The tradition remembers him fasting there, singing to Vitthal, for thirteen days.","art":"art/story/sm/fk-tukaram-notebooks.jpg","route":"#/story/fk.tukaram-notebooks|s3","cta":"Read from here","why":"A moment from The Notebooks That Came Back","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.tukaram-notebooks-5":{"src":"story:fk.tukaram-notebooks:scenes:5:text","title":"The Notebooks That Came Back · 6 of 8","body":"Word of it ran through the villages like the river itself. The message everyone took was the one the learned objectors least wanted: heaven, apparently, had no quarrel with Marathi. The god of Pandharpur would not let the kitchen-language poems drown.","art":"art/story/sm/fk-tukaram-notebooks.jpg","route":"#/story/fk.tukaram-notebooks|s5","cta":"Read from here","why":"A moment from The Notebooks That Came Back","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.tukaram-notebooks-6":{"src":"story:fk.tukaram-notebooks:scenes:6:text","title":"The Notebooks That Came Back · 7 of 8","body":"The Warkaris have sung those abhangs from that day to this. Millions know them by heart — on the Pandharpur road, in the fields, at bedtime. Sinking the notebooks, it turned out, was the least effective thing anyone ever did to a book of poems.","art":"art/story/sm/fk-tukaram-notebooks.jpg","route":"#/story/fk.tukaram-notebooks|s6","cta":"Read from here","why":"A moment from The Notebooks That Came Back","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.hirkani-cliff-1":{"src":"story:fk.hirkani-cliff:scenes:1:text","title":"Hirkani's Wall · 2 of 8","body":"Every morning, women from the villages below climbed the long fort path to sell milk — among them, the katha says, a young Gavli milkmaid named Hirkani, quick on the path, with a baby son at home in the village.","art":"art/story/sm/fk-hirkani-cliff.jpg","route":"#/story/fk.hirkani-cliff|s1","cta":"Read from here","why":"A moment from Hirkani's Wall","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.hirkani-cliff-2":{"src":"story:fk.hirkani-cliff:scenes:2:text","title":"Hirkani's Wall · 3 of 8","body":"One evening the selling ran late, and the sunset gun sounded, and the great gates of Raigad swung shut — as they did every night, opening for no one until dawn. That was the fort's iron rule, and it had kept the fort alive. Hirkani was on the wrong side of it. Her baby was below.","art":"art/story/sm/fk-hirkani-cliff.jpg","route":"#/story/fk.hirkani-cliff|s2","cta":"Read from here","why":"A moment from Hirkani's Wall","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.hirkani-cliff-3":{"src":"story:fk.hirkani-cliff:scenes:3:text","title":"Hirkani's Wall · 4 of 8","body":"She begged at the gate. The guards were sorry — genuinely sorry — and did not open it. Rules that bend for one person are not rules. She stood in the dusk with the whole night ahead, and her feet, almost by themselves, took her along the wall to where the wall ended: the cliff edge.","art":"art/story/sm/fk-hirkani-cliff.jpg","route":"#/story/fk.hirkani-cliff|s3","cta":"Read from here","why":"A moment from Hirkani's Wall","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.hirkani-cliff-5":{"src":"story:fk.hirkani-cliff:scenes:5:text","title":"Hirkani's Wall · 6 of 8","body":"In the morning the story reached Shivaji. A guard expected fury — the fort's unclimbable cliff, climbed by a milkmaid. The katha says the king sent for Hirkani, heard her out, and honoured her: a sari, gifts, and his open admiration for a courage his soldiers would struggle to match.","art":"art/story/sm/fk-hirkani-cliff.jpg","route":"#/story/fk.hirkani-cliff|s5","cta":"Read from here","why":"A moment from Hirkani's Wall","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.hirkani-cliff-6":{"src":"story:fk.hirkani-cliff:scenes:6:text","title":"Hirkani's Wall · 7 of 8","body":"And then he did the thing the katha treasures most. Where she had climbed down, he ordered the wall extended — and named the new bastion after her. Not after a general. After the milkmaid. Hirkani Buruj: Hirkani's Tower.","art":"art/story/sm/fk-hirkani-cliff.jpg","route":"#/story/fk.hirkani-cliff|s6","cta":"Read from here","why":"A moment from Hirkani's Wall","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.gir-maldhari-1":{"src":"story:fk.gir-maldhari:scenes:1:text","title":"The Forest With Two Kinds of Families · 2 of 8","body":"Deep inside Gir live the Maldharis — herding families whose settlements, called nesses, sit right in the lion's forest. Thorn-fence corrals, mud houses, and herds of big black buffaloes. Maldhari means keeper of animals; they have grazed these lands for generations beyond memory.","art":"art/story/sm/fk-gir-maldhari.jpg","route":"#/story/fk.gir-maldhari|s1","cta":"Read from here","why":"A moment from The Forest With Two Kinds of Families","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.gir-maldhari-2":{"src":"story:fk.gir-maldhari:scenes:2:text","title":"The Forest With Two Kinds of Families · 3 of 8","body":"Which means Maldhari children grow up in a way almost no other children on Earth do: with wild lions as neighbours. Not lions in an enclosure. Lions on the path to the water, lions calling across the night, lions resting in the shade a field away.","art":"art/story/sm/fk-gir-maldhari.jpg","route":"#/story/fk.gir-maldhari|s2","cta":"Read from here","why":"A moment from The Forest With Two Kinds of Families","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.gir-maldhari-3":{"src":"story:fk.gir-maldhari:scenes:3:text","title":"The Forest With Two Kinds of Families · 4 of 8","body":"Ask a Maldhari elder how that can possibly work and he will tell you it works on manners — the lions' and theirs. \"We know their ways, they know ours,\" he will say. \"Neither side surprises the other. Surprise is the only real danger.\"","art":"art/story/sm/fk-gir-maldhari.jpg","route":"#/story/fk.gir-maldhari|s3","cta":"Read from here","why":"A moment from The Forest With Two Kinds of Families","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.gir-maldhari-5":{"src":"story:fk.gir-maldhari:scenes:5:text","title":"The Forest With Two Kinds of Families · 6 of 8","body":"A century ago the lions were nearly gone — down to a few dozen. What saved them was protection begun by the rulers of Junagadh and carried on by foresters since; and what has kept the saving alive is this: a forest where the people who live closest to lions choose, daily, to live with them.","art":"art/story/sm/fk-gir-maldhari.jpg","route":"#/story/fk.gir-maldhari|s5","cta":"Read from here","why":"A moment from The Forest With Two Kinds of Families","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.gir-maldhari-6":{"src":"story:fk.gir-maldhari:scenes:6:text","title":"The Forest With Two Kinds of Families · 7 of 8","body":"Today the lions number in the hundreds and have spread beyond the forest edges, walking coolly past farms and temples of Saurashtra, greeted mostly with pride. Ask a Gujarati about the Gir lion and watch their back straighten.","art":"art/story/sm/fk-gir-maldhari.jpg","route":"#/story/fk.gir-maldhari|s6","cta":"Read from here","why":"A moment from The Forest With Two Kinds of Families","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.garba-lamp-1":{"src":"story:fk.garba-lamp:scenes:1:text","title":"The Lamp Inside the Pot · 2 of 8","body":"And at the centre of the circles, where you might expect a stage or a star performer, sits something humble: a clay pot, pierced all over with little holes, with an oil lamp burning inside. The pot is the garbo. The dance is named after it. Everything turns around that small light.","art":"art/story/sm/fk-garba-lamp.jpg","route":"#/story/fk.garba-lamp|s1","cta":"Read from here","why":"A moment from The Lamp Inside the Pot","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.garba-lamp-2":{"src":"story:fk.garba-lamp:scenes:2:text","title":"The Lamp Inside the Pot · 3 of 8","body":"A girl at her first Navratri asked her mother the right question: \"Why do we dance around a pot?\" Her mother took her to the centre and let her look at it properly — the clay, the holes, the flame glowing out through each one.","art":"art/story/sm/fk-garba-lamp.jpg","route":"#/story/fk.garba-lamp|s2","cta":"Read from here","why":"A moment from The Lamp Inside the Pot","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.garba-lamp-3":{"src":"story:fk.garba-lamp:scenes:3:text","title":"The Lamp Inside the Pot · 4 of 8","body":"The nine nights belong to the Devi — the Mother Goddess in her many forms, honoured with fasting by day and dancing by night. In many families the garbo is installed at home too, the lamp kept burning, the household's own small centre for the festival.","art":"art/story/sm/fk-garba-lamp.jpg","route":"#/story/fk.garba-lamp|s3","cta":"Read from here","why":"A moment from The Lamp Inside the Pot","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.garba-lamp-5":{"src":"story:fk.garba-lamp:scenes:5:text","title":"The Lamp Inside the Pot · 6 of 8","body":"Grandmothers dance the slow inner circles, teenagers spin in the fast outer ones, and the claps come down on the same beat from a thousand hands. Then the dandiya sticks come out and the circles become clashing, laughing rivers. Nobody needs a rehearsal. Gujarat has been rehearsing for centuries.","art":"art/story/sm/fk-garba-lamp.jpg","route":"#/story/fk.garba-lamp|s5","cta":"Read from here","why":"A moment from The Lamp Inside the Pot","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.garba-lamp-6":{"src":"story:fk.garba-lamp:scenes:6:text","title":"The Lamp Inside the Pot · 7 of 8","body":"Wherever Gujarati families have gone in the world — and they have gone everywhere — Navratri goes too. In halls in London and New Jersey and Nairobi, the same circles turn around the same small lamp, and children who have never seen Gujarat learn the steps their great-grandmothers knew.","art":"art/story/sm/fk-garba-lamp.jpg","route":"#/story/fk.garba-lamp|s6","cta":"Read from here","why":"A moment from The Lamp Inside the Pot","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.kutch-flamingo-1":{"src":"story:fk.kutch-flamingo:scenes:1:text","title":"The Pink City in the Salt · 2 of 8","body":"Then the monsoon comes, and the sea and the rivers push shallow water out over the salt, and the Rann becomes an enormous glittering mirror, ankle-deep for mile after mile. And out of the sky, in long pink skeins, the flamingos arrive — in their tens of thousands.","art":"art/story/sm/fk-kutch-flamingo.jpg","route":"#/story/fk.kutch-flamingo|s1","cta":"Read from here","why":"A moment from The Pink City in the Salt","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.kutch-flamingo-2":{"src":"story:fk.kutch-flamingo:scenes:2:text","title":"The Pink City in the Salt · 3 of 8","body":"Far out in that shallow water, on mudflats no road reaches, they build their city. Each pair heaps up a little tower of mud, a nest like a tiny volcano, thousands upon thousands of them packed together. Ornithologists who first mapped it gave the place its perfect name: Flamingo City.","art":"art/story/sm/fk-kutch-flamingo.jpg","route":"#/story/fk.kutch-flamingo|s2","cta":"Read from here","why":"A moment from The Pink City in the Salt","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.kutch-flamingo-3":{"src":"story:fk.kutch-flamingo:scenes:3:text","title":"The Pink City in the Salt · 4 of 8","body":"A child looking at that white emptiness asks the obvious: why here? Of all the green, comfortable places in India, why do the flamingos build their nursery in a salt desert?","art":"art/story/sm/fk-kutch-flamingo.jpg","route":"#/story/fk.kutch-flamingo|s3","cta":"Read from here","why":"A moment from The Pink City in the Salt","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.kutch-flamingo-5":{"src":"story:fk.kutch-flamingo:scenes:5:text","title":"The Pink City in the Salt · 6 of 8","body":"The people of Kutch — herders, salt-workers, craftspeople whose embroidery is famous across the world — have always shared their strange land with these visitors, and Gujarat honours the bird: the flamingo is the state bird, and the great Rann gatherings are counted a treasure.","art":"art/story/sm/fk-kutch-flamingo.jpg","route":"#/story/fk.kutch-flamingo|s5","cta":"Read from here","why":"A moment from The Pink City in the Salt","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.kutch-flamingo-6":{"src":"story:fk.kutch-flamingo:scenes:6:text","title":"The Pink City in the Salt · 7 of 8","body":"In a good year, when rain and water levels are kind, a lakh and more flamingos may gather in the Rann — one of the great bird spectacles on Earth, blooming out of the emptiest-looking place in the country. Then the water dries, the city empties, and the white silence returns to wait.","art":"art/story/sm/fk-kutch-flamingo.jpg","route":"#/story/fk.kutch-flamingo|s6","cta":"Read from here","why":"A moment from The Pink City in the Salt","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.narsinh-hundi-1":{"src":"story:fk.narsinh-hundi:scenes:1:text","title":"The Note of Trust · 2 of 8","body":"This is the katha Gujarat loves best about him. A party of pilgrims was setting out for Dwarka, Krishna's city on the far coast, and the road was long and unsafe for a purse. In those days travellers used hundis — a note of money paid to a trusted man in one town, to be redeemed from his partner in another.","art":"art/story/sm/fk-narsinh-hundi.jpg","route":"#/story/fk.narsinh-hundi|s1","cta":"Read from here","why":"A moment from The Note of Trust","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.narsinh-hundi-2":{"src":"story:fk.narsinh-hundi:scenes:2:text","title":"The Note of Trust · 3 of 8","body":"Someone in Junagadh — mischievous, or spiteful, the tellings differ — pointed the pilgrims to Narsinh Mehta's house: \"He has dealings in Dwarka.\" The joke being that the poet owned almost nothing but his cymbals. The pilgrims knocked and asked: would he write them a hundi payable in Dwarka?","art":"art/story/sm/fk-narsinh-hundi.jpg","route":"#/story/fk.narsinh-hundi|s2","cta":"Read from here","why":"A moment from The Note of Trust","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.narsinh-hundi-3":{"src":"story:fk.narsinh-hundi:scenes:3:text","title":"The Note of Trust · 4 of 8","body":"The pilgrims reached Dwarka and asked the bazaar for the great merchant Shamalsha Seth. The bazaar had never heard of him. The pilgrims stood in the street with a worthless paper, hot with anger, deciding exactly what they would say to that fraud of a poet back in Junagadh.","art":"art/story/sm/fk-narsinh-hundi.jpg","route":"#/story/fk.narsinh-hundi|s3","cta":"Read from here","why":"A moment from The Note of Trust","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.narsinh-hundi-5":{"src":"story:fk.narsinh-hundi:scenes:5:text","title":"The Note of Trust · 6 of 8","body":"Krishna himself had come as the merchant, the tradition says — because his bhakta had signed trust over to him, and that particular signature he has never once dishonoured. The pilgrims came home telling it, and Junagadh's laughter turned to something quieter.","art":"art/story/sm/fk-narsinh-hundi.jpg","route":"#/story/fk.narsinh-hundi|s5","cta":"Read from here","why":"A moment from The Note of Trust","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.narsinh-hundi-6":{"src":"story:fk.narsinh-hundi:scenes:6:text","title":"The Note of Trust · 7 of 8","body":"Gujarat has sung Narsinh Mehta's songs ever since — at prayer, at festivals, in the morning ragas — and told this katha alongside them: the poorest man in town, whose credit was good in heaven.","art":"art/story/sm/fk-narsinh-hundi.jpg","route":"#/story/fk.narsinh-hundi|s6","cta":"Read from here","why":"A moment from The Note of Trust","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.mandvi-ships-1":{"src":"story:fk.mandvi-ships:scenes:1:text","title":"The Ships Built by Hand · 2 of 8","body":"The builders are mostly of the Kharva community, Mandvi's hereditary seafarers and shipwrights, and the yards run on family lines — a boy learns holding nails for his father, who learned holding nails for his. The adze, the auger, the plane: tools a shipwright of centuries ago would pick up without a question.","art":"art/story/sm/fk-mandvi-ships.jpg","route":"#/story/fk.mandvi-ships|s1","cta":"Read from here","why":"A moment from The Ships Built by Hand","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.mandvi-ships-2":{"src":"story:fk.mandvi-ships:scenes:2:text","title":"The Ships Built by Hand · 3 of 8","body":"Now the astonishing part. Ask the master builder — the mistri — for the ship's drawings, and he will tap his forehead. There are none. No blueprint, no computer model. The whole ship — every curve of every rib, hundreds of tonnes of future vessel — is held in his head, and measured out with string, rods and forty years of eye.","art":"art/story/sm/fk-mandvi-ships.jpg","route":"#/story/fk.mandvi-ships|s2","cta":"Read from here","why":"A moment from The Ships Built by Hand","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.mandvi-ships-3":{"src":"story:fk.mandvi-ships:scenes:3:text","title":"The Ships Built by Hand · 4 of 8","body":"A visitor once asked a mistri how anyone can keep a whole ship in his head. The old man thought about it while his hands went on checking a plank's edge, entirely unsupervised.","art":"art/story/sm/fk-mandvi-ships.jpg","route":"#/story/fk.mandvi-ships|s3","cta":"Read from here","why":"A moment from The Ships Built by Hand","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.mandvi-ships-5":{"src":"story:fk.mandvi-ships:scenes:5:text","title":"The Ships Built by Hand · 6 of 8","body":"And the yards are no museum. Orders still come — from Gulf traders, from companies wanting stout wooden vessels — and the dhows still go down the Rukmavati into the sea, diesel-engined now, but hulls shaped exactly as the great-great-grandfathers shaped them.","art":"art/story/sm/fk-mandvi-ships.jpg","route":"#/story/fk.mandvi-ships|s5","cta":"Read from here","why":"A moment from The Ships Built by Hand","facts":[["From","The Western Lands"],["Read","4 min"]]},"ss-fk.mandvi-ships-6":{"src":"story:fk.mandvi-ships:scenes:6:text","title":"The Ships Built by Hand · 7 of 8","body":"Watch a launch if you ever can: an entire handmade ship, blessed with coconut and prayer, easing into the water in front of the families who built it — every plank of it pulled out of memory, and the memory holding true.","art":"art/story/sm/fk-mandvi-ships.jpg","route":"#/story/fk.mandvi-ships|s6","cta":"Read from here","why":"A moment from The Ships Built by Hand","facts":[["From","The Western Lands"],["Read","4 min"]]},"en-mahabharata-18-1":{"route":"#/epic/mahabharata|18","act":{"a":"episode","id":"mahabharata","n":18},"src":"epic:mahabharata:episodes:17:cards:1:text","title":"The Mahabharata · What Karna Would Not Refuse","body":"It was not a boast. It was the one thing he had made entirely by himself, without a father's name or a kingdom given to him by somebody else. It was his, and it was the only thing that was.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 18","facts":[["Epic","The Mahabharata"],["Night","18 of 33"]]},"en-mahabharata-18-2":{"route":"#/epic/mahabharata|18","act":{"a":"episode","id":"mahabharata","n":18},"src":"epic:mahabharata:episodes:17:cards:2:text","title":"The Mahabharata · What Karna Would Not Refuse","body":"And he had that armour. Not worn — grown. It was part of his skin, it had been there since the basket, and nothing anybody could throw would go through it. Which was a serious problem for anybody who might one day have to fight him.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 18","facts":[["Epic","The Mahabharata"],["Night","18 of 33"]]},"en-mahabharata-18-3":{"route":"#/epic/mahabharata|18","act":{"a":"episode","id":"mahabharata","n":18},"src":"epic:mahabharata:episodes:17:cards:3:text","title":"The Mahabharata · What Karna Would Not Refuse","body":"So the sun woke him in a dream. \"Listen to me. Tomorrow morning a poor man is going to come to you at the water and ask for your armour. He is not a poor man. He is Indra, and he has a son who is going to have to face you one day, and he is frightened.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 18","facts":[["Epic","The Mahabharata"],["Night","18 of 33"]]},"en-mahabharata-18-4":{"route":"#/epic/mahabharata|18","act":{"a":"episode","id":"mahabharata","n":18},"src":"epic:mahabharata:episodes:17:cards:4:text","title":"The Mahabharata · What Karna Would Not Refuse","body":"\"Say no. Once. Just this one morning, for me. It will cost you nothing and it will save your life.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 18","facts":[["Epic","The Mahabharata"],["Night","18 of 33"]]},"en-mahabharata-18-6":{"route":"#/epic/mahabharata|18","act":{"a":"episode","id":"mahabharata","n":18},"src":"epic:mahabharata:episodes:17:cards:6:text","title":"The Mahabharata · What Karna Would Not Refuse","body":"\"I have exactly one thing in this world that is mine,\" he said. \"Not my name. Not my kingdom, which was a gift. Just this — that nobody who asks me in the morning walks away with empty hands. If I keep the armour and lose that, what is left standing at the water? Let him have the skin. Leave me the rule.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 18","facts":[["Epic","The Mahabharata"],["Night","18 of 33"]]},"en-mahabharata-18-7":{"route":"#/epic/mahabharata|18","act":{"a":"episode","id":"mahabharata","n":18},"src":"epic:mahabharata:episodes:17:cards:7:text","title":"The Mahabharata · What Karna Would Not Refuse","body":"The sun, who could not talk him out of it, did what the parents of extremely stubborn children do, and negotiated. \"Then at least ask him for something back. He will owe you. Ask for the spear.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 18","facts":[["Epic","The Mahabharata"],["Night","18 of 33"]]},"en-mahabharata-18-8":{"route":"#/epic/mahabharata|18","act":{"a":"episode","id":"mahabharata","n":18},"src":"epic:mahabharata:episodes:17:cards:8:text","title":"The Mahabharata · What Karna Would Not Refuse","body":"In the morning a poor man came to the water and asked, and Karna cut the armour away from his own body, which hurt in a way the poem does not dwell on, and handed it over dripping and smiling and said, \"Take it. And now I will ask you for something.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 18","facts":[["Epic","The Mahabharata"],["Night","18 of 33"]]},"en-mahabharata-18-9":{"route":"#/epic/mahabharata|18","act":{"a":"episode","id":"mahabharata","n":18},"src":"epic:mahabharata:episodes:17:cards:9:text","title":"The Mahabharata · What Karna Would Not Refuse","body":"He got a spear that would kill any one person in the world, once, and then be finished. One throw, one life, and then nothing. He carried it for years and thought about it every single day.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 18","facts":[["Epic","The Mahabharata"],["Night","18 of 33"]]},"en-mahabharata-19-1":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:1:text","title":"The Mahabharata · The Voice in the Lake","body":"Nakula climbed a tree and saw green, and went off to bring water back, and did not come back. Sahadeva went to look for him and did not come back. Arjuna went. Bhima went. Nobody came back.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-19-2":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:2:text","title":"The Mahabharata · The Voice in the Lake","body":"So Yudhishthira went, and found a beautiful clear lake, and his four brothers lying on the bank around it, not moving. No wound on any of them. No mark. No sign of anybody having been there at all.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-19-3":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:3:text","title":"The Mahabharata · The Voice in the Lake","body":"He knelt down and put his hands in the water, and a voice came out of the lake. \"That water is mine. They drank without answering me. You may drink after you answer, and not before.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-19-4":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:4:text","title":"The Mahabharata · The Voice in the Lake","body":"\"Then ask,\" said Yudhishthira, who was the thirstiest man in the world, kneeling between his four dead brothers, and who did not argue about it for even one second. That is why this episode is his.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-19-5":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:5:text","title":"The Mahabharata · The Voice in the Lake","body":"\"What is faster than the wind?\" \"The mind.\" \"What travels alone?\" \"The sun.\" \"What do you leave behind when you go?\" \"Everything except what you did.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-19-7":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:7:text","title":"The Mahabharata · The Voice in the Lake","body":"\"Last one,\" said the voice. \"What is the most astonishing thing in the whole world?\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-19-8":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:8:text","title":"The Mahabharata · The Voice in the Lake","body":"\"That every day,\" said Yudhishthira, \"people watch other people die. And every day they get up and live as though it is never going to happen to them. There is nothing stranger than that anywhere.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-19-9":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:9:text","title":"The Mahabharata · The Voice in the Lake","body":"\"Correct,\" said the voice. \"Choose one of your brothers. I will give you one. He will get up and the other three will not.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-19-10":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:10:text","title":"The Mahabharata · The Voice in the Lake","body":"Yudhishthira did not even take long. \"Nakula.\" Not Bhima, who was the strongest. Not Arjuna, who was the war. \"My father had two wives. I am alive, and I am Kunti's. One of Madri's sons should be alive too. If I am going to spend my life talking about what is fair I should probably start at home.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-19-11":{"route":"#/epic/mahabharata|19","act":{"a":"episode","id":"mahabharata","n":19},"src":"epic:mahabharata:episodes:18:cards:11:text","title":"The Mahabharata · The Voice in the Lake","body":"And the voice said that this was the answer it had come for, and all four brothers sat up at once, complaining and asking what had happened, and the thing in the lake turned out to be Dharma himself, who was Yudhishthira's own father.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19","facts":[["Epic","The Mahabharata"],["Night","19 of 33"]]},"en-mahabharata-20-1":{"route":"#/epic/mahabharata|20","act":{"a":"episode","id":"mahabharata","n":20},"src":"epic:mahabharata:episodes:19:cards:1:text","title":"The Mahabharata · The Year Nobody Knew Them","body":"First they had to hide the weapons. They wrapped them in cloth and tied them high in a tree near the burning ground and told the local people it was a body, because nobody goes near one of those, which is the only reason it worked.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20","facts":[["Epic","The Mahabharata"],["Night","20 of 33"]]},"en-mahabharata-20-2":{"route":"#/epic/mahabharata|20","act":{"a":"episode","id":"mahabharata","n":20},"src":"epic:mahabharata:episodes:19:cards:2:text","title":"The Mahabharata · The Year Nobody Knew Them","body":"Yudhishthira became Kanka, a quiet gentleman who played dice with the king. He was extremely good at it now. He had had a lot of time to think about dice.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20","facts":[["Epic","The Mahabharata"],["Night","20 of 33"]]},"en-mahabharata-20-3":{"route":"#/epic/mahabharata|20","act":{"a":"episode","id":"mahabharata","n":20},"src":"epic:mahabharata:episodes:19:cards:3:text","title":"The Mahabharata · The Year Nobody Knew Them","body":"Bhima became Ballava the cook, and he was a genuinely brilliant cook, and he also won every wrestling match in the kingdom by accident and had to be told to stop.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20","facts":[["Epic","The Mahabharata"],["Night","20 of 33"]]},"en-mahabharata-20-4":{"route":"#/epic/mahabharata|20","act":{"a":"episode","id":"mahabharata","n":20},"src":"epic:mahabharata:episodes:19:cards:4:text","title":"The Mahabharata · The Year Nobody Knew Them","body":"The twins took the horses and the cattle. And Arjuna — the greatest archer in the world, who had once been taught to sing and dance by the musicians of the sky, and had thought it a waste of time — put on bangles and a long braid, took the name Brihannala, and became the teacher of dance to the princess.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20","facts":[["Epic","The Mahabharata"],["Night","20 of 33"]]},"en-mahabharata-20-5":{"route":"#/epic/mahabharata|20","act":{"a":"episode","id":"mahabharata","n":20},"src":"epic:mahabharata:episodes:19:cards:5:text","title":"The Mahabharata · The Year Nobody Knew Them","body":"And Draupadi, who had been queen of the finest city in the world, became Sairandhri, a hairdresser to the queen, on the condition that she serve no one else and be asked nothing about herself.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20","facts":[["Epic","The Mahabharata"],["Night","20 of 33"]]},"en-mahabharata-20-7":{"route":"#/epic/mahabharata|20","act":{"a":"episode","id":"mahabharata","n":20},"src":"epic:mahabharata:episodes:19:cards:7:text","title":"The Mahabharata · The Year Nobody Knew Them","body":"She went to Yudhishthira. He told her to endure it, because of the year, because of the thirteen, because of the word he had given. He failed her a second time, in a smaller room, with less excuse.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20","facts":[["Epic","The Mahabharata"],["Night","20 of 33"]]},"en-mahabharata-20-8":{"route":"#/epic/mahabharata|20","act":{"a":"episode","id":"mahabharata","n":20},"src":"epic:mahabharata:episodes:19:cards:8:text","title":"The Mahabharata · The Year Nobody Knew Them","body":"So she went to Bhima at night in the kitchen, and Bhima did not tell her to endure anything. That man was found dead in the dancing hall in the morning, and the entire court took one look and quietly decided not to ask a single question about it.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20","facts":[["Epic","The Mahabharata"],["Night","20 of 33"]]},"en-mahabharata-20-9":{"route":"#/epic/mahabharata|20","act":{"a":"episode","id":"mahabharata","n":20},"src":"epic:mahabharata:episodes:19:cards:9:text","title":"The Mahabharata · The Year Nobody Knew Them","body":"\"We told the king it must have been a spirit,\" said one of Virata's ministers afterwards, \"because the alternative was that we had a cook who could do that, and nobody wanted to think about the cook.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20","facts":[["Epic","The Mahabharata"],["Night","20 of 33"]]},"en-mahabharata-20-10":{"route":"#/epic/mahabharata|20","act":{"a":"episode","id":"mahabharata","n":20},"src":"epic:mahabharata:episodes:19:cards:10:text","title":"The Mahabharata · The Year Nobody Knew Them","body":"Draupadi got through the year. But she got through it as a servant, being told to wait, by the man who had already staked her once — and the poem never once suggests she should be grateful about it.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20","facts":[["Epic","The Mahabharata"],["Night","20 of 33"]]},"en-mahabharata-21-1":{"route":"#/epic/mahabharata|21","act":{"a":"episode","id":"mahabharata","n":21},"src":"epic:mahabharata:episodes:20:cards:1:text","title":"The Mahabharata · The Prince Who Ran Away","body":"Virata and his army were away at the far border. The only person left in the palace was his son, Prince Uttara, who had spent his whole life explaining at dinner exactly what he would do if he ever got the chance.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21","facts":[["Epic","The Mahabharata"],["Night","21 of 33"]]},"en-mahabharata-21-2":{"route":"#/epic/mahabharata|21","act":{"a":"episode","id":"mahabharata","n":21},"src":"epic:mahabharata:episodes:20:cards:2:text","title":"The Mahabharata · The Prince Who Ran Away","body":"\"I would go out this minute,\" he announced to the women's hall, \"if only I had a charioteer. There is simply nobody left who can drive.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21","facts":[["Epic","The Mahabharata"],["Night","21 of 33"]]},"en-mahabharata-21-3":{"route":"#/epic/mahabharata|21","act":{"a":"episode","id":"mahabharata","n":21},"src":"epic:mahabharata:episodes:20:cards:3:text","title":"The Mahabharata · The Prince Who Ran Away","body":"And the princess, who had been having dance lessons for eleven months, said brightly: \"Brihannala can drive. Brihannala told me. Take Brihannala.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21","facts":[["Epic","The Mahabharata"],["Night","21 of 33"]]},"en-mahabharata-21-4":{"route":"#/epic/mahabharata|21","act":{"a":"episode","id":"mahabharata","n":21},"src":"epic:mahabharata:episodes:20:cards:4:text","title":"The Mahabharata · The Prince Who Ran Away","body":"So the prince of the kingdom rode out to face the greatest army in the world with a dance teacher in bangles holding the reins, which is exactly the sort of thing this poem does when it has been serious for too long.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21","facts":[["Epic","The Mahabharata"],["Night","21 of 33"]]},"en-mahabharata-21-5":{"route":"#/epic/mahabharata|21","act":{"a":"episode","id":"mahabharata","n":21},"src":"epic:mahabharata:episodes:20:cards:5:text","title":"The Mahabharata · The Prince Who Ran Away","body":"They came over the rise and Uttara saw it. The whole line of it. Bhishma's banner. Drona's. Karna's. And he dropped his bow in the chariot and jumped down and ran, actually ran, back towards the city, with his arms going.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21","facts":[["Epic","The Mahabharata"],["Night","21 of 33"]]},"en-mahabharata-21-7":{"route":"#/epic/mahabharata|21","act":{"a":"episode","id":"mahabharata","n":21},"src":"epic:mahabharata:episodes:20:cards:7:text","title":"The Mahabharata · The Prince Who Ran Away","body":"They stopped at a burning ground where something long was wrapped in cloth up in a tree. \"Fetch that down.\" \"That is a body.\" \"It is not a body. Fetch it down.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21","facts":[["Epic","The Mahabharata"],["Night","21 of 33"]]},"en-mahabharata-21-8":{"route":"#/epic/mahabharata|21","act":{"a":"episode","id":"mahabharata","n":21},"src":"epic:mahabharata:episodes:20:cards:8:text","title":"The Mahabharata · The Prince Who Ran Away","body":"The boy climbed the tree and unwrapped a bow that he had heard about in songs since he was four years old, and turned round very slowly to look at his dance teacher.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21","facts":[["Epic","The Mahabharata"],["Night","21 of 33"]]},"en-mahabharata-21-9":{"route":"#/epic/mahabharata|21","act":{"a":"episode","id":"mahabharata","n":21},"src":"epic:mahabharata:episodes:20:cards:9:text","title":"The Mahabharata · The Prince Who Ran Away","body":"And out across the field the sound of that bowstring reached the old men, and Bhishma turned to Drona, and Drona said, \"That is Arjuna. Count the days again if it makes you feel better. I already have. The year is over.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21","facts":[["Epic","The Mahabharata"],["Night","21 of 33"]]},"en-mahabharata-21-10":{"route":"#/epic/mahabharata|21","act":{"a":"episode","id":"mahabharata","n":21},"src":"epic:mahabharata:episodes:20:cards:10:text","title":"The Mahabharata · The Prince Who Ran Away","body":"One man, one terrified boy driving, against all of them. He did not kill anybody. He simply took the army apart, put them all to sleep with one arrow at the end, and had Uttara collect the cattle and drive home.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21","facts":[["Epic","The Mahabharata"],["Night","21 of 33"]]},"en-mahabharata-24-1":{"route":"#/epic/mahabharata|24","act":{"a":"episode","id":"mahabharata","n":24},"src":"epic:mahabharata:episodes:23:cards:1:text","title":"The Mahabharata · Kunti at the Water","body":"When he finished he turned round and found the mother of the five men he was about to fight standing in the sun with her head uncovered, and he bowed and gave her his proper name — the son of the chariot driver and Radha — because that is who he had decided long ago that he was.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24","facts":[["Epic","The Mahabharata"],["Night","24 of 33"]]},"en-mahabharata-24-2":{"route":"#/epic/mahabharata|24","act":{"a":"episode","id":"mahabharata","n":24},"src":"epic:mahabharata:episodes:23:cards:2:text","title":"The Mahabharata · Kunti at the Water","body":"\"No,\" she said. \"Listen. I was thirteen. There were words a man had given me and I did not understand what they did. I said them at a window, looking at the sun, to see if they were real.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24","facts":[["Epic","The Mahabharata"],["Night","24 of 33"]]},"en-mahabharata-24-3":{"route":"#/epic/mahabharata|24","act":{"a":"episode","id":"mahabharata","n":24},"src":"epic:mahabharata:episodes:23:cards:3:text","title":"The Mahabharata · Kunti at the Water","body":"\"You were born that evening with the armour already on you. I put you in a basket and I pushed you into the river before it was light, and I have not said one word about it to any living person since, and I am saying it now.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24","facts":[["Epic","The Mahabharata"],["Night","24 of 33"]]},"en-mahabharata-24-4":{"route":"#/epic/mahabharata|24","act":{"a":"episode","id":"mahabharata","n":24},"src":"epic:mahabharata:episodes:23:cards:4:text","title":"The Mahabharata · Kunti at the Water","body":"He did not shout. That is the terrible part. Everybody in this poem shouts eventually except him, in this one conversation.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24","facts":[["Epic","The Mahabharata"],["Night","24 of 33"]]},"en-mahabharata-24-5":{"route":"#/epic/mahabharata|24","act":{"a":"episode","id":"mahabharata","n":24},"src":"epic:mahabharata:episodes:23:cards:5:text","title":"The Mahabharata · Kunti at the Water","body":"\"You had forty years,\" he said. \"You had the whole afternoon in that arena, when they asked me my father's name in front of thirty thousand people and I stood there with nothing to say. You were in the gallery. I have been told where you were sitting.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24","facts":[["Epic","The Mahabharata"],["Night","24 of 33"]]},"en-mahabharata-24-7":{"route":"#/epic/mahabharata|24","act":{"a":"episode","id":"mahabharata","n":24},"src":"epic:mahabharata:episodes:23:cards:7:text","title":"The Mahabharata · Kunti at the Water","body":"She did not deny it. That is one of the bravest things in the book. She had come for exactly that, and she stood there and let him say it.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24","facts":[["Epic","The Mahabharata"],["Night","24 of 33"]]},"en-mahabharata-24-8":{"route":"#/epic/mahabharata|24","act":{"a":"episode","id":"mahabharata","n":24},"src":"epic:mahabharata:episodes:23:cards:8:text","title":"The Mahabharata · Kunti at the Water","body":"\"I will not leave Duryodhana,\" he said. \"He gave me a kingdom on a day when nobody in the world would give me the time. Whatever he is — and I know what he is — he did that, and I will not be the man who walks away the week it gets expensive.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24","facts":[["Epic","The Mahabharata"],["Night","24 of 33"]]},"en-mahabharata-24-9":{"route":"#/epic/mahabharata|24","act":{"a":"episode","id":"mahabharata","n":24},"src":"epic:mahabharata:episodes:23:cards:9:text","title":"The Mahabharata · Kunti at the Water","body":"\"But I will give you this. You came for five sons and you will go home with five. I will not touch Yudhishthira. Not Bhima, not Nakula, not Sahadeva. Only Arjuna. One of us will be alive at the end and you will still have five.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24","facts":[["Epic","The Mahabharata"],["Night","24 of 33"]]},"en-mahabharata-24-10":{"route":"#/epic/mahabharata|24","act":{"a":"episode","id":"mahabharata","n":24},"src":"epic:mahabharata:episodes:23:cards:10:text","title":"The Mahabharata · Kunti at the Water","body":"And Kunti walked back to the camp with that, and told nobody, and went on saying nothing for as long as it took, which by now she was extremely good at.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24","facts":[["Epic","The Mahabharata"],["Night","24 of 33"]]},"en-mahabharata-27-1":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:1:text","title":"The Mahabharata · The Fall of Bhishma","body":"So on the ninth night the five of them walked across to the other camp, unarmed, at night, and went into the tent of the man who was destroying them. Nobody stopped them. Everybody in both armies understood exactly what this family was.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-27-2":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:2:text","title":"The Mahabharata · The Fall of Bhishma","body":"\"You said to come and ask,\" said Yudhishthira. \"I am asking.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-27-3":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:3:text","title":"The Mahabharata · The Fall of Bhishma","body":"\"Yes,\" said Bhishma. \"I did say that.\" And he sat and told them, calmly, how to end him, because he had promised to answer and because he was extremely tired.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-27-4":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:4:text","title":"The Mahabharata · The Fall of Bhishma","body":"There was a warrior on their side called Shikhandi, who had been born a girl and was now a man, and against whom Bhishma had decided long ago that he would never raise a bow. Put Shikhandi in front, he said, and put Arjuna behind him.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-27-5":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:5:text","title":"The Mahabharata · The Fall of Bhishma","body":"They walked back to their own camp in the dark, and nobody spoke, and Arjuna was sick that night. It is the worst thing he is ever asked to do and it is not close.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-27-7":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:7:text","title":"The Mahabharata · The Fall of Bhishma","body":"He went down. He did not reach the ground. There were so many arrows in him that he came to rest on them, held up above the earth, and the whole war stopped, on both sides, at once, without anybody giving an order.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-27-8":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:8:text","title":"The Mahabharata · The Fall of Bhishma","body":"They came and stood round him, everybody, from both armies, and somebody ran for silk cushions to put under his head, and the old man laughed at them.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-27-9":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:9:text","title":"The Mahabharata · The Fall of Bhishma","body":"\"Not those. A soldier's pillow.\" And Arjuna, crying, put three arrows in the ground under his grandfather's head. \"That is right,\" said Bhishma. \"That is from my own family.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-27-10":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:10:text","title":"The Mahabharata · The Fall of Bhishma","body":"Then he said he was thirsty, and they brought water in a jar and he would not take it, so Arjuna shot one arrow into the earth beside him and clean water came up out of the ground, and the old man drank and said, \"Now you are showing off,\" and closed his eyes.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-27-11":{"route":"#/epic/mahabharata|27","act":{"a":"episode","id":"mahabharata","n":27},"src":"epic:mahabharata:episodes:26:cards:11:text","title":"The Mahabharata · The Fall of Bhishma","body":"And he did not die. He had been given the choosing of his own hour when he was young, and he decided to wait — so he lay on that field, on those arrows, all through the rest of the war and for a long time after it, while both sides came and sat with him and asked him questions.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27","facts":[["Epic","The Mahabharata"],["Night","27 of 33"]]},"en-mahabharata-29-1":{"route":"#/epic/mahabharata|29","act":{"a":"episode","id":"mahabharata","n":29},"src":"epic:mahabharata:episodes:28:cards:1:text","title":"The Mahabharata · Three Words in a Loud Room","body":"There was exactly one thing on earth that would make him stop, and everybody knew what it was. He had a son called Ashwatthama, and he loved him past all sense, and if he believed his son was dead he would put the bow down where he stood.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29","facts":[["Epic","The Mahabharata"],["Night","29 of 33"]]},"en-mahabharata-29-2":{"route":"#/epic/mahabharata|29","act":{"a":"episode","id":"mahabharata","n":29},"src":"epic:mahabharata:episodes:28:cards:2:text","title":"The Mahabharata · Three Words in a Loud Room","body":"So somebody said it out loud in the tent, and everybody looked at Yudhishthira, because there was no point telling Drona a lie unless it came from the one man in the world who had never told one.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29","facts":[["Epic","The Mahabharata"],["Night","29 of 33"]]},"en-mahabharata-29-3":{"route":"#/epic/mahabharata|29","act":{"a":"episode","id":"mahabharata","n":29},"src":"epic:mahabharata:episodes:28:cards:3:text","title":"The Mahabharata · Three Words in a Loud Room","body":"\"He will not believe me,\" said Krishna. \"He will not believe Bhima. He will believe you, and only you, and he will believe you the first time. That is what your whole life has bought.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29","facts":[["Epic","The Mahabharata"],["Night","29 of 33"]]},"en-mahabharata-29-4":{"route":"#/epic/mahabharata|29","act":{"a":"episode","id":"mahabharata","n":29},"src":"epic:mahabharata:episodes:28:cards:4:text","title":"The Mahabharata · Three Words in a Loud Room","body":"Yudhishthira said no. And then he said no again. And then he stood there while the day went on and people he had grown up with were carried past the tent, and he stopped saying no, and that is the actual moment, not what comes after.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29","facts":[["Epic","The Mahabharata"],["Night","29 of 33"]]},"en-mahabharata-29-5":{"route":"#/epic/mahabharata|29","act":{"a":"episode","id":"mahabharata","n":29},"src":"epic:mahabharata:episodes:28:cards:5:text","title":"The Mahabharata · Three Words in a Loud Room","body":"They found a way to make it nearly true. There was an elephant in the army whose name happened to be Ashwatthama. Bhima went and killed the elephant, and then walked up and down the line shouting that Ashwatthama was dead, and the drums were enormous.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29","facts":[["Epic","The Mahabharata"],["Night","29 of 33"]]},"en-mahabharata-29-7":{"route":"#/epic/mahabharata|29","act":{"a":"episode","id":"mahabharata","n":29},"src":"epic:mahabharata:episodes:28:cards:7:text","title":"The Mahabharata · Three Words in a Loud Room","body":"\"Ashwatthama is dead,\" said Yudhishthira. And then, in a voice that would not have carried three feet in that noise, he added: \"...the elephant.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29","facts":[["Epic","The Mahabharata"],["Night","29 of 33"]]},"en-mahabharata-29-8":{"route":"#/epic/mahabharata|29","act":{"a":"episode","id":"mahabharata","n":29},"src":"epic:mahabharata:episodes:28:cards:8:text","title":"The Mahabharata · Three Words in a Loud Room","body":"Drona did not hear it. Nobody heard it. He got down off his chariot in the middle of a battle, put his bow on the floor of it, sat down, and closed his eyes, and stopped being in the war at all.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29","facts":[["Epic","The Mahabharata"],["Night","29 of 33"]]},"en-mahabharata-29-9":{"route":"#/epic/mahabharata|29","act":{"a":"episode","id":"mahabharata","n":29},"src":"epic:mahabharata:episodes:28:cards:9:text","title":"The Mahabharata · Three Words in a Loud Room","body":"And Drupada's son, who had been born into this family's quarrel and raised for precisely this one moment, came and did it while the old man was sitting there, and nobody on either side felt anything you could call victory.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29","facts":[["Epic","The Mahabharata"],["Night","29 of 33"]]},"en-mahabharata-29-10":{"route":"#/epic/mahabharata|29","act":{"a":"episode","id":"mahabharata","n":29},"src":"epic:mahabharata:episodes:28:cards:10:text","title":"The Mahabharata · Three Words in a Loud Room","body":"The best man in the poem told his one lie, and it worked, and the poem never lets him have it back. It is not on the list of things he is forgiven for. He carries it to the very last page, and it is waiting for him there.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29","facts":[["Epic","The Mahabharata"],["Night","29 of 33"]]},"en-mahabharata-30-1":{"route":"#/epic/mahabharata|30","act":{"a":"episode","id":"mahabharata","n":30},"src":"epic:mahabharata:episodes:29:cards:1:text","title":"The Mahabharata · The Wheel in the Mud","body":"He kept his word to Kunti the whole way through. He had Yudhishthira in front of him and let him go. He had Bhima and let him go. Four times he could have ended it and four times he stepped back, and nobody on his own side ever understood why.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30","facts":[["Epic","The Mahabharata"],["Night","30 of 33"]]},"en-mahabharata-30-2":{"route":"#/epic/mahabharata|30","act":{"a":"episode","id":"mahabharata","n":30},"src":"epic:mahabharata:episodes:29:cards:2:text","title":"The Mahabharata · The Wheel in the Mud","body":"And he had used the spear. The one throw he had bought with his own skin, the one he had been saving for Arjuna for years — he had been forced to spend it the night before, on somebody else, to save Duryodhana. He knew what that meant when he did it.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30","facts":[["Epic","The Mahabharata"],["Night","30 of 33"]]},"en-mahabharata-30-3":{"route":"#/epic/mahabharata|30","act":{"a":"episode","id":"mahabharata","n":30},"src":"epic:mahabharata:episodes:29:cards:3:text","title":"The Mahabharata · The Wheel in the Mud","body":"On the seventeenth day the two chariots finally came together, and it was the fight the whole poem has been walking towards since a boy walked into an arena and asked for a match.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30","facts":[["Epic","The Mahabharata"],["Night","30 of 33"]]},"en-mahabharata-30-4":{"route":"#/epic/mahabharata|30","act":{"a":"episode","id":"mahabharata","n":30},"src":"epic:mahabharata:episodes:29:cards:4:text","title":"The Mahabharata · The Wheel in the Mud","body":"And then his chariot wheel went into the ground. Soft earth, a bad line, an ordinary accident, and the wheel sank to the axle and the horses could not pull it out.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30","facts":[["Epic","The Mahabharata"],["Night","30 of 33"]]},"en-mahabharata-30-5":{"route":"#/epic/mahabharata|30","act":{"a":"episode","id":"mahabharata","n":30},"src":"epic:mahabharata:episodes:29:cards:5:text","title":"The Mahabharata · The Wheel in the Mud","body":"He reached for the great weapon he had been taught, and the words for it would not come. He had been cursed once, long ago, over something small, that at the moment he most needed it he would not be able to remember — and he stood in his chariot with his mind completely blank.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30","facts":[["Epic","The Mahabharata"],["Night","30 of 33"]]},"en-mahabharata-30-6":{"route":"#/epic/mahabharata|30","act":{"a":"episode","id":"mahabharata","n":30},"src":"epic:mahabharata:episodes:29:cards:6:text","title":"The Mahabharata · The Wheel in the Mud","body":"So he put his bow down, and got out, and put his shoulder to the wheel, and called across to the other chariot: \"Wait. A man on foot with no weapon. That is the rule. We wrote it. Wait until I am up.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30","facts":[["Epic","The Mahabharata"],["Night","30 of 33"]]},"en-mahabharata-30-8":{"route":"#/epic/mahabharata|30","act":{"a":"episode","id":"mahabharata","n":30},"src":"epic:mahabharata:episodes:29:cards:8:text","title":"The Mahabharata · The Wheel in the Mud","body":"\"The rule,\" said Krishna. \"Say it again. Where was the rule when six of you closed a wheel round a boy of sixteen and broke his bow? Where was it in that hall, when a woman asked a question and you were in the room, and you spoke, and you did not speak kindly? You cannot pick the afternoon you start keeping the rules.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30","facts":[["Epic","The Mahabharata"],["Night","30 of 33"]]},"en-mahabharata-30-9":{"route":"#/epic/mahabharata|30","act":{"a":"episode","id":"mahabharata","n":30},"src":"epic:mahabharata:episodes:29:cards:9:text","title":"The Mahabharata · The Wheel in the Mud","body":"\"Shoot, Arjuna.\"","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30","facts":[["Epic","The Mahabharata"],["Night","30 of 33"]]},"en-mahabharata-30-10":{"route":"#/epic/mahabharata|30","act":{"a":"episode","id":"mahabharata","n":30},"src":"epic:mahabharata:episodes:29:cards:10:text","title":"The Mahabharata · The Wheel in the Mud","body":"And he did. And you are allowed to find that unbearable, because it is meant to be. The poem puts the two worst things it knows side by side on one page and does not tell you which one is worse. That is not the poem failing. That is the poem.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30","facts":[["Epic","The Mahabharata"],["Night","30 of 33"]]}});
